/* =========================================================
   SUPABASE / CLOUD
========================================================= */

function getSession() {

    try {

        return JSON.parse(
            localStorage.getItem(
                SESSION_KEY
            )
        ) || null;

    } catch (error) {

        return null;

    }

}


function setSession(value) {

    session = value;


    if (value) {

        localStorage.setItem(
            SESSION_KEY,
            JSON.stringify(value)
        );

    } else {

        localStorage.removeItem(
            SESSION_KEY
        );

    }

}


/* =========================================================
   HEADERS TIL SUPABASE
========================================================= */

function authHeaders(
    token = session?.access_token
) {

    const headers = {

        apikey:
            SUPABASE_KEY,

        "Content-Type":
            "application/json"

    };


    if (token) {

        headers.Authorization =
            `Bearer ${token}`;

    }


    return headers;

}


/* =========================================================
   SUPABASE REQUEST
========================================================= */

async function supabaseRequest(
    path,
    options = {}
) {

    if (!cloudConfigured) {

        throw new Error(
            "Supabase er ikke konfigureret endnu."
        );

    }


    const response =
        await fetch(
            `${SUPABASE_URL}${path}`,
            {

                ...options,

                headers: {

                    ...authHeaders(),

                    ...(options.headers || {})

                }

            }
        );


    const text =
        await response.text();


    let data = null;


    try {

        data =
            text
                ? JSON.parse(text)
                : null;

    } catch (error) {

        data = text;

    }


    if (!response.ok) {

        const message =

            data?.msg ||

            data?.message ||

            data?.error_description ||

            data?.error ||

            `HTTP ${response.status}`;


        throw new Error(
            message
        );

    }


    return data;

}


/* =========================================================
   REFRESH LOGIN
========================================================= */

async function refreshSession() {

    if (
        !session?.refresh_token
    ) {

        return false;

    }


    const oldSession =
        session;


    try {

        const response =
            await fetch(
                `${SUPABASE_URL}/auth/v1/token?grant_type=refresh_token`,
                {

                    method:
                        "POST",

                    headers: {

                        apikey:
                            SUPABASE_KEY,

                        "Content-Type":
                            "application/json"

                    },

                    body:
                        JSON.stringify({

                            refresh_token:
                                oldSession.refresh_token

                        })

                }
            );


        const text =
            await response.text();


        let data =
            null;


        try {

            data =
                text
                    ? JSON.parse(text)
                    : null;

        } catch (error) {

            data =
                null;

        }


        if (
            !response.ok ||
            !data?.access_token
        ) {

            throw new Error(
                data?.message ||
                data?.error_description ||
                data?.error ||
                `HTTP ${response.status}`
            );

        }


        const refreshedSession = {

            ...oldSession,
            ...data,

            refresh_token:
                data.refresh_token ||
                oldSession.refresh_token,

            user:
                data.user ||
                oldSession.user

        };


        setSession(
            refreshedSession
        );


        return true;

    } catch (error) {

        console.error(
            "Kunne ikke refreshe login:",
            error
        );


        session =
            oldSession;


        return Boolean(
            oldSession?.access_token
        );

    }

}



/* =========================================================
   TJEK LOGIN
========================================================= */

async function ensureSession() {

    if (
        !cloudConfigured
    ) {

        return false;

    }


    session =
        getSession();


    if (
        !session
    ) {

        return false;

    }


    if (
        session.expires_at &&
        Date.now() / 1000 >
            session.expires_at - 60
    ) {

        return await refreshSession();

    }


    return true;

}


