/* =========================================================
   PDF BANE
========================================================= */

function lavPDFBane() {

    const formation =
        formationer[
            formationSelector.value
        ];


    let playersHTML =
        "";


    formation.forEach(
        (position, index) => {

            const [
                rolle,
                x,
                y
            ] = position;


            const spiller =
                spillere[index];


            if (!spiller) {
                return;
            }


            const keeper =
                spiller.position === "GK";


            playersHTML += `

                <div
                    class="pdf-player-slot"
                    style="
                        left:${x}%;
                        top:${y}%;
                    "
                >

                    <div
                        class="
                            pdf-shirt
                            ${keeper
                                ? "goalkeeper"
                                : ""}
                        "
                    >
                        ${escapeHTML(
                            spiller.number
                        )}
                    </div>


                    <div class="pdf-player-name">
                        ${escapeHTML(
                            spiller.name
                        )}
                    </div>

                </div>

            `;

        }
    );


    return `

        <div class="pdf-pitch">


            <div class="pdf-pitch-lines">

                <div class="pdf-halfway"></div>

                <div class="pdf-center-circle"></div>

                <div class="pdf-center-dot"></div>

                <div class="
                    pdf-penalty
                    top
                "></div>

                <div class="
                    pdf-goal
                    top
                "></div>

                <div class="
                    pdf-penalty
                    bottom
                "></div>

                <div class="
                    pdf-goal
                    bottom
                "></div>

            </div>


            ${playersHTML}

        </div>

    `;
}

function lavPDFUdskiftere() {

    if (
        !udskiftere.length
    ) {

        return "";

    }


    return `

        <div class="pdf-substitutes">

            <div class="pdf-substitutes-title">
                UDSKIFTERE
            </div>


            <div class="pdf-substitutes-list">

                ${
                    udskiftere
                        .map(
                            spiller => `

                                <div class="pdf-substitute">

                                    <span class="pdf-substitute-number">
                                        #${escapeHTML(
                                            spiller.number
                                        )}
                                    </span>

                                    <span>
                                        ${escapeHTML(
                                            spiller.name
                                        )}
                                    </span>

                                </div>

                            `
                        )
                        .join("")
                }

            </div>

        </div>

    `;

}

/* =========================================================
   SPILLERE PDF
========================================================= */

function lavSpillerePDF() {

const aktive = [

    ...spillere
        .filter(Boolean)
        .map(
            spiller => ({
                ...spiller,
                pdfPlayerStatus:
                    "STARTOPSTILLING"
            })
        ),

    ...udskiftere
        .filter(Boolean)
        .map(
            spiller => ({
                ...spiller,
                pdfPlayerStatus:
                    "UDSKIFTER"
            })
        )

];


    if (
        aktive.length === 0
    ) {

        return `
            <section class="pdf-page">

                <div class="pdf-content">

                    <h1 class="pdf-heading">
                        Spillerspecifikke fokuspunkter
                    </h1>

                    <div class="pdf-box">
                        Ingen spillere tilføjet endnu.
                    </div>

                </div>

                <div class="pdf-footer">
                    SPILLERSPECIFIKKE FOKUSPUNKTER
                </div>

            </section>
        `;

    }


    let sider = [];


    for (
        let i = 0;
        i < aktive.length;
        i += 3
    ) {

        sider.push(`

            <section class="pdf-page">

                <div class="pdf-content">

                    <h1 class="pdf-heading">
                        Spillerspecifikke fokuspunkter
                    </h1>

                    ${
                        aktive
                            .slice(
                                i,
                                i + 3
                            )
                            .map(
                                spiller =>
                                    lavSpillerPDF(
                                        spiller
                                    )
                            )
                            .join("")
                    }

                </div>

                <div class="pdf-footer">
                    SPILLERSPECIFIKKE FOKUSPUNKTER
                </div>

            </section>

        `);

    }


    return sider.join("");

}


