/* =========================================================
   LISTE
========================================================= */

function lavListe(
    tekst
) {

    if (
        !tekst
    ) {

        return `

            <div class="trait-list">

                <li>
                    Ingen tilføjet endnu.
                </li>

            </div>

        `;

    }


    const items =
        tekst
            .split(/\n|,/)
            .filter(
                item =>
                    item.trim()
            );


    return `

        <ul class="trait-list">

            ${
                items
                    .map(
                        item => `

                            <li>

                                <span class="check-icon">
                                    ✓
                                </span>

                                ${escapeHTML(
                                    item.trim()
                                )}

                            </li>

                        `
                    )
                    .join("")
            }

        </ul>

    `;
}


/* =========================================================
   DATO
========================================================= */

function formaterDato(
    dato
) {

    if (
        !dato
    ) {

        return "";

    }


    const parts =
        dato.split("-");


    if (
        parts.length !== 3
    ) {

        return dato;

    }


    return `${parts[2]}/${parts[1]}/${parts[0]}`;

}


/* =========================================================
   ESCAPE HTML
========================================================= */

function escapeHTML(
    value
) {

    if (
        value === null ||
        value === undefined
    ) {

        return "";

    }


    return String(value)

        .replace(
            /&/g,
            "&amp;"
        )

        .replace(
            /</g,
            "&lt;"
        )

        .replace(
            />/g,
            "&gt;"
        )

        .replace(
            /"/g,
            "&quot;"
        )

        .replace(
            /'/g,
            "&#039;"
        );

}


/* =========================================================
   NOTIFICATION
========================================================= */

function visNotification(
    tekst
) {

    notification.textContent =
        tekst;


    notification.classList.add(
        "show"
    );


    setTimeout(
        function() {

            notification.classList.remove(
                "show"
            );

        },
        2500
    );

}


