/* =========================================================
   HOLD – SYNKRONISERINGSTID
========================================================= */

function formatTeamSyncTime(
    value
) {

    if (!value) {

        return "Ikke synkroniseret endnu";

    }


    const date =
        new Date(
            value
        );


    if (
        Number.isNaN(
            date.getTime()
        )
    ) {

        return "Ukendt";

    }


    const diff =
        Date.now() -
        date.getTime();


    if (
        diff >= 0 &&
        diff < 60000
    ) {

        return "Nu";

    }


    if (
        diff >= 0 &&
        diff < 3600000
    ) {

        return (
            Math.max(
                1,
                Math.floor(
                    diff / 60000
                )
            ) +
            " min siden"
        );

    }


    return date.toLocaleString(
        "da-DK",
        {

            day:
                "2-digit",

            month:
                "2-digit",

            year:
                date.getFullYear() !==
                new Date().getFullYear()
                    ? "numeric"
                    : undefined,

            hour:
                "2-digit",

            minute:
                "2-digit"

        }
    );

}


/* =========================================================
   MINE HOLD – RENDER
========================================================= */

function renderTeamsDashboard() {

    const list =
        document.getElementById(
            "teamsDashboardList"
        );


    if (!list) {

        return;

    }


    list.innerHTML =
        "";


    if (
        !cloudTeams.length
    ) {

        list.innerHTML = `
            <div class="team-dashboard-card">

                <div class="team-card-main">

                    <div class="team-card-name">
                        Ingen hold endnu
                    </div>

                    <div class="team-sync-text">
                        Opret dit første hold nedenfor.
                    </div>

                </div>

            </div>
        `;

        return;

    }


    cloudTeams.forEach(
        team => {

            const card =
                document.createElement(
                    "div"
                );


            card.className =
                "team-dashboard-card" +
                (
                    team.id ===
                    activeTeamId
                        ? " active"
                        : ""
                );


            card.dataset.teamId =
                team.id;


            /* -------------------------
               VENSTRE DEL
            ------------------------- */

            const main =
                document.createElement(
                    "div"
                );


            main.className =
                "team-card-main";


            const titleRow =
                document.createElement(
                    "div"
                );


            titleRow.className =
                "team-card-title-row";


            const name =
                document.createElement(
                    "div"
                );


            name.className =
                "team-card-name";


            name.textContent =
                team.name ||
                "Mit hold";


            titleRow.appendChild(
                name
            );


            if (
                team.id ===
                activeTeamId
            ) {

                const activeBadge =
                    document.createElement(
                        "span"
                    );


                activeBadge.className =
                    "team-active-badge";


                activeBadge.textContent =
                    "AKTIVT HOLD";


                titleRow.appendChild(
                    activeBadge
                );

            }


            const sync =
                document.createElement(
                    "div"
                );


            sync.className =
                "team-sync-text";


            sync.textContent =
                "Sidst synkroniseret: " +
                formatTeamSyncTime(
                    team.updated_at
                );


            main.append(
                titleRow,
                sync
            );


            main.addEventListener(
                "click",
                async () => {

                    if (
                        team.id ===
                        activeTeamId
                    ) {

                        return;

                    }


                    await changeTeam(
                        team.id
                    );


                    renderTeamsDashboard();

                }
            );


            /* -------------------------
               KNAPPER
            ------------------------- */

            const actions =
                document.createElement(
                    "div"
                );


            actions.className =
                "team-card-actions";


            /* OMDØB */

            const rename =
                document.createElement(
                    "button"
                );


            rename.type =
                "button";


            rename.className =
                "team-icon-button";


            rename.title =
                "Omdøb hold";


            rename.setAttribute(
                "aria-label",
                `Omdøb ${team.name}`
            );


            rename.textContent =
                "✎";


            rename.addEventListener(
                "click",
                event => {

                    event.stopPropagation();


                    showRenameTeamRow(
                        card,
                        team
                    );

                }
            );


            /* SLET */

            const del =
                document.createElement(
                    "button"
                );


            del.type =
                "button";


            del.className =
                "team-icon-button delete";


            del.title =
                "Slet hold";


            del.setAttribute(
                "aria-label",
                `Slet ${team.name}`
            );


            del.textContent =
                "🗑";


            del.addEventListener(
                "click",
                async event => {

                    event.stopPropagation();


                    await deleteTeamFromDashboard(
                        team.id
                    );

                }
            );


            actions.append(
                rename,
                del
            );


            card.append(
                main,
                actions
            );


            list.appendChild(
                card
            );

        }
    );

}


/* =========================================================
   OMDØB HOLD
========================================================= */

function showRenameTeamRow(
    card,
    team
) {

    const existing =
        card.querySelector(
            ".team-rename-row"
        );


    if (existing) {

        existing
            .querySelector(
                "input"
            )
            ?.focus();


        return;

    }


    const row =
        document.createElement(
            "div"
        );


    row.className =
        "team-rename-row";


    row.style.gridColumn =
        "1 / -1";


    const input =
        document.createElement(
            "input"
        );


    input.type =
        "text";


    input.maxLength =
        60;


    input.value =
        team.name ||
        "";


    input.setAttribute(
        "aria-label",
        "Nyt holdnavn"
    );


    const save =
        document.createElement(
            "button"
        );


    save.type =
        "button";


    save.className =
        "start11-secondary-button";


    save.textContent =
        "GEM";


    const submit =
        async () => {

            const newName =
                input.value.trim();


            if (
                !newName ||
                newName === team.name
            ) {

                row.remove();

                return;

            }


            await renameCloudTeam(
                team.id,
                newName
            );

        };


    save.addEventListener(
        "click",
        submit
    );


    input.addEventListener(
        "keydown",
        event => {

            if (
                event.key ===
                "Enter"
            ) {

                submit();

            }


            if (
                event.key ===
                "Escape"
            ) {

                row.remove();

            }

        }
    );


    row.append(
        input,
        save
    );


    card.appendChild(
        row
    );


    input.focus();

    input.select();

}


/* =========================================================
   GEM NYT HOLDNAVN
========================================================= */

async function renameCloudTeam(
    teamId,
    newName
) {

    const team =
        cloudTeams.find(
            item =>
                item.id ===
                teamId
        );


    if (
        !team ||
        !newName.trim()
    ) {

        return;

    }


    try {

        const updatedAt =
            new Date().toISOString();


        await supabaseRequest(
            `/rest/v1/${CLOUD_TABLE}?id=eq.${encodeURIComponent(teamId)}`,
            {

                method:
                    "PATCH",

                headers: {

                    Prefer:
                        "return=minimal"

                },

                body:
                    JSON.stringify({

                        name:
                            newName.trim(),

                        updated_at:
                            updatedAt

                    })

            }
        );


        team.name =
            newName.trim();


        team.updated_at =
            updatedAt;


        updateTeamSelector();

        renderTeamsDashboard();


        visNotification(
            "Holdet er omdøbt."
        );

    } catch (error) {

        visNotification(
            "Kunne ikke omdøbe hold: " +
            error.message
        );

    }

}


/* =========================================================
   SLET HOLD
========================================================= */

async function deleteTeamFromDashboard(
    teamId
) {

    const team =
        cloudTeams.find(
            item =>
                item.id ===
                teamId
        );


    if (!team) {

        return;

    }


    if (
        cloudTeams.length <= 1
    ) {

        visNotification(
            "Du skal have mindst ét hold på din konto."
        );

        return;

    }


    const accepted =
        confirm(
            `Vil du slette "${team.name}"? Denne handling kan ikke fortrydes.`
        );


    if (!accepted) {

        return;

    }


    try {

        if (
            teamId ===
            activeTeamId
        ) {

            await saveCloudNow();

        }


        await supabaseRequest(
            `/rest/v1/${CLOUD_TABLE}?id=eq.${encodeURIComponent(teamId)}`,
            {

                method:
                    "DELETE",

                headers: {

                    Prefer:
                        "return=minimal"

                }

            }
        );


        cloudTeams =
            cloudTeams.filter(
                item =>
                    item.id !==
                    teamId
            );


        if (
            teamId ===
            activeTeamId
        ) {

            const nextTeam =
                cloudTeams[0];


            activeTeamId =
                null;


            localStorage.removeItem(
                ACTIVE_TEAM_KEY
            );


            if (nextTeam) {

                activeTeamId =
                    nextTeam.id;


                localStorage.setItem(
                    ACTIVE_TEAM_KEY,
                    nextTeam.id
                );


                applyTeamData(
                    nextTeam.data
                );

            }

        }


        updateTeamSelector();

        renderTeamsDashboard();


        visNotification(
            `${team.name} er slettet.`
        );

    } catch (error) {

        visNotification(
            "Kunne ikke slette hold: " +
            error.message
        );

    }

}


