/* =========================================================
   KONTO – DISPLAY DATA
========================================================= */

function getAccountDisplayData() {

    const user =
        session?.user ||
        null;


    const email =
        user?.email ||
        "";


    let name =
        user?.user_metadata?.full_name ||
        user?.user_metadata?.name ||
        "";


    if (
        !name &&
        email
    ) {

        name =
            email
                .split("@")[0]
                .replace(
                    /[._-]+/g,
                    " "
                )
                .trim()
                .split(" ")
                .filter(Boolean)
                .map(
                    word =>
                        word.charAt(0).toUpperCase() +
                        word.slice(1)
                )
                .join(" ");

    }


    name =
        name ||
        "Bruger";


    const initials =
        name
            .split(/\s+/)
            .filter(Boolean)
            .slice(
                0,
                2
            )
            .map(
                part =>
                    part
                        .charAt(0)
                        .toUpperCase()
            )
            .join("") ||
        "U";


    return {

        name,
        email,
        initials

    };

}


/* =========================================================
   KONTOINDSTILLINGER – RENDER
========================================================= */

function renderAccountSettings() {

    const {
        name,
        email,
        initials
    } =
        getAccountDisplayData();


    const avatar =
        document.getElementById(
            "settingsAvatar"
        );


    const displayName =
        document.getElementById(
            "settingsDisplayName"
        );


    const profileEmail =
        document.getElementById(
            "settingsProfileEmail"
        );


    const nameInput =
        document.getElementById(
            "settingsNameInput"
        );


    const emailInput =
        document.getElementById(
            "settingsEmailInput"
        );


    if (avatar) {

        avatar.textContent =
            initials;

    }


    if (displayName) {

        displayName.textContent =
            name;

    }


    if (profileEmail) {

        profileEmail.textContent =
            email;

    }


    if (nameInput) {

        nameInput.value =
            name;

    }


    if (emailInput) {

        emailInput.value =
            email;

    }

}


/* =========================================================
   GEM PROFIL
========================================================= */

async function saveAccountProfile() {

    const input =
        document.getElementById(
            "settingsNameInput"
        );


    const fullName =
        input?.value?.trim();


    if (
        !session ||
        !fullName
    ) {

        visNotification(
            "Skriv dit navn først."
        );


        return;

    }


    try {

        const updatedUser =
            await supabaseRequest(
                "/auth/v1/user",
                {

                    method:
                        "PUT",

                    body:
                        JSON.stringify({

                            data: {

                                full_name:
                                    fullName

                            }

                        })

                }
            );


        session.user =
            updatedUser;


        setSession(
            session
        );


        updateAccountUI();

        renderAccountSettings();


        visNotification(
            "Profilen er opdateret."
        );

    } catch (error) {

        visNotification(
            "Kunne ikke gemme profilen: " +
            error.message
        );

    }

}


/* =========================================================
   SKIFT ADGANGSKODE
========================================================= */

async function changeAccountPassword() {

    const password =
        document.getElementById(
            "newPasswordInput"
        )?.value ||
        "";


    const confirmPassword =
        document.getElementById(
            "confirmPasswordInput"
        )?.value ||
        "";


    if (
        password.length < 6
    ) {

        visNotification(
            "Adgangskoden skal være mindst 6 tegn."
        );


        return;

    }


    if (
        password !==
        confirmPassword
    ) {

        visNotification(
            "Adgangskoderne er ikke ens."
        );


        return;

    }


    try {

        const updatedUser =
            await supabaseRequest(
                "/auth/v1/user",
                {

                    method:
                        "PUT",

                    body:
                        JSON.stringify({

                            password

                        })

                }
            );


        if (
            updatedUser?.id &&
            session
        ) {

            session.user =
                updatedUser;


            setSession(
                session
            );

        }


        const passwordInput =
            document.getElementById(
                "newPasswordInput"
            );


        const passwordConfirmInput =
            document.getElementById(
                "confirmPasswordInput"
            );


        if (passwordInput) {

            passwordInput.value =
                "";

        }


        if (passwordConfirmInput) {

            passwordConfirmInput.value =
                "";

        }


        visNotification(
            "Adgangskoden er ændret."
        );

    } catch (error) {

        visNotification(
            "Kunne ikke ændre adgangskode: " +
            error.message
        );

    }

}


