window.addEventListener(
    "beforeunload",
    () => {

        /*
            localStorage gemmes synkront.

            Cloud-request kan browseren ikke garantere
            bliver færdig under beforeunload, derfor
            er localStorage vores fallback.
        */

        localStorage.setItem(
            "startopstillingSpillere",
            JSON.stringify(
                spillere
            )
        );


        localStorage.setItem(
            "startopstillingUdskiftere",
            JSON.stringify(
                udskiftere
            )
        );


        localStorage.setItem(
            "kampplan",
            JSON.stringify(
                kampplan
            )
        );


        localStorage.setItem(
            "start11Formation",
            formationSelector.value
        );

    }
);


/* =========================================================
   INITIALISERING
========================================================= */

async function initialiserStart11() {

    /*
        Sørg for at spillere altid har 11 pladser.
    */

    if (
        !Array.isArray(
            spillere
        )
    ) {

        spillere =
            Array(11).fill(
                null
            );

    }


    while (
        spillere.length < 11
    ) {

        spillere.push(
            null
        );

    }


    if (
        spillere.length > 11
    ) {

        spillere =
            spillere.slice(
                0,
                11
            );

    }


    /*
        Formation fra localStorage.
    */

    if (
        formationer[
            currentFormation
        ]
    ) {

        formationSelector.value =
            currentFormation;

    } else {

        currentFormation =
            "4-4-2";


        formationSelector.value =
            "4-4-2";

    }


    /*
        Tegn lokal version først.
        Det gør at appen starter hurtigt,
        også hvis cloud er langsom.
    */

    opdaterKampTitel();


    tegnOpstilling();


    opdaterUdskiftere();


    opdaterBilledePreview(
        "homeLogo",
        kampplan.homeLogo
    );


    opdaterBilledePreview(
        "awayLogo",
        kampplan.awayLogo
    );


    opdaterBilledePreview(
        "background",
        kampplan.backgroundImage
    );


    /*
        Cloud er valgfrit indtil URL og key
        er indsat.
    */

    if (
        !cloudConfigured
    ) {

        updateAccountUI();


        const status =
            document.getElementById(
                "cloudStatus"
            );


        if (status) {

            status.textContent =
                "Cloud ikke konfigureret";

        }


        console.info(
            "START11: Supabase er ikke konfigureret endnu."
        );


        return;

    }


    /*
        Se om der allerede ligger en session.
    */

    const loggedIn =
        await ensureSession();


    if (
        loggedIn
    ) {

        updateAccountUI();


        await loadCloudTeams();

    } else {

        updateAccountUI();


        /*
            Når cloud er konfigureret, men brugeren
            ikke er logget ind, viser vi login.
        */

        showLogin();

    }

}


/* =========================================================
   START11 – DASHBOARD / TRUP ADDITIONS
   LÆG DENNE BLOK HELT NEDERST I DIN NUVÆRENDE start11.js.

   VIGTIGT:
   - Den omskriver ikke drag/drop-funktionerne.
   - Den bruger de eksisterende spillere/udskiftere/kampplan.
   - Hele truppen gemmes separat, så "ikke udtaget" ikke slettes.
========================================================= */

const START11_SQUAD_KEY = "start11FullSquad";
const START11_DBU_URL_KEY = "start11DbuTeamUrl";
const START11_MATCHES_KEY = "start11DashboardMatches";

let start11FullSquad = [];
let start11EditingSquadPlayerId = null;
let start11SquadView = "match";


function start11MakeId() {

    if (
        typeof crypto !== "undefined" &&
        typeof crypto.randomUUID === "function"
    ) {

        return crypto.randomUUID();

    }


    return (
        "s11_" +
        Date.now().toString(36) +
        "_" +
        Math.random().toString(36).slice(2)
    );

}


function start11ReadJson(
    key,
    fallback
) {

    try {

        const value =
            JSON.parse(
                localStorage.getItem(key)
            );


        return value ?? fallback;

    } catch (error) {

        return fallback;

    }

}


function start11NormalizeSquadPlayer(
    player,
    selected = false
) {

    return {

        id:
            player?.squadId ||
            player?.id ||
            start11MakeId(),

        name:
            player?.name ||
            "",

        number:
            player?.number ||
            "",

        position:
            player?.position ||
            "CM",

        status:
            player?.squadStatus ||
            player?.status ||
            "available",

        selected:
            typeof player?.selected === "boolean"
                ? player.selected
                : selected

    };

}


function start11LoadFullSquad() {

    const saved =
        start11ReadJson(
            START11_SQUAD_KEY,
            []
        );


    if (
        Array.isArray(saved) &&
        saved.length
    ) {

        start11FullSquad =
            saved.map(
                player =>
                    start11NormalizeSquadPlayer(
                        player,
                        Boolean(player.selected)
                    )
            );

        return;

    }


    /*
        Første gang funktionen bruges:
        byg truppen ud fra den nuværende
        startopstilling + bænk.
    */

    const combined = [

        ...(Array.isArray(spillere)
            ? spillere.filter(Boolean)
            : []),

        ...(Array.isArray(udskiftere)
            ? udskiftere.filter(Boolean)
            : [])

    ];


    combined.forEach(
        player => {

            const alreadyExists =
                start11FullSquad.some(
                    squadPlayer =>
                        start11SamePlayer(
                            squadPlayer,
                            player
                        )
                );


            if (
                !alreadyExists
            ) {

                start11FullSquad.push(
                    start11NormalizeSquadPlayer(
                        player,
                        true
                    )
                );

            }

        }
    );


    start11SaveFullSquad();

}


function start11SamePlayer(
    a,
    b
) {

    const aName =
        String(
            a?.name || ""
        )
            .trim()
            .toLocaleLowerCase("da-DK");


    const bName =
        String(
            b?.name || ""
        )
            .trim()
            .toLocaleLowerCase("da-DK");


    if (
        !aName ||
        !bName
    ) {

        return false;

    }


    const aNumber =
        String(
            a?.number || ""
        ).trim();


    const bNumber =
        String(
            b?.number || ""
        ).trim();


    return (
        aName === bName &&
        (
            !aNumber ||
            !bNumber ||
            aNumber === bNumber
        )
    );

}


function start11SaveFullSquad() {

    localStorage.setItem(
        START11_SQUAD_KEY,
        JSON.stringify(
            start11FullSquad
        )
    );

}


function start11SyncSquadFromCurrentMatch() {

    const starters =
        Array.isArray(spillere)
            ? spillere.filter(Boolean)
            : [];


    const substitutes =
        Array.isArray(udskiftere)
            ? udskiftere.filter(Boolean)
            : [];


    const selectedPlayers = [
        ...starters,
        ...substitutes
    ];


    selectedPlayers.forEach(
        player => {

            let squadPlayer =
                start11FullSquad.find(
                    item =>
                        start11SamePlayer(
                            item,
                            player
                        )
                );


            if (
                !squadPlayer
            ) {

                squadPlayer =
                    start11NormalizeSquadPlayer(
                        player,
                        true
                    );


                start11FullSquad.push(
                    squadPlayer
                );

            }


            squadPlayer.name =
                player.name ||
                squadPlayer.name;


            squadPlayer.number =
                player.number ||
                squadPlayer.number;


            squadPlayer.position =
                player.position ||
                squadPlayer.position;


            squadPlayer.selected =
                true;

        }
    );


    start11SaveFullSquad();

}


function start11GetPlayerRole(
    squadPlayer
) {

    const starterIndex =
        Array.isArray(spillere)
            ? spillere.findIndex(
                player =>
                    player &&
                    start11SamePlayer(
                        squadPlayer,
                        player
                    )
            )
            : -1;


    if (
        starterIndex !== -1
    ) {

        return "starting";

    }


    const substituteIndex =
        Array.isArray(udskiftere)
            ? udskiftere.findIndex(
                player =>
                    player &&
                    start11SamePlayer(
                        squadPlayer,
                        player
                    )
            )
            : -1;


    if (
        substituteIndex !== -1
    ) {

        return "substitute";

    }


    return squadPlayer.selected
        ? "selected"
        : "not-selected";

}


function start11StatusLabel(
    status
) {

    if (
        status === "injured"
    ) {

        return "Skadet";

    }


    if (
        status === "unavailable"
    ) {

        return "Ikke klar";

    }


    return "Tilgængelig";

}


function start11RoleLabel(
    role
) {

    if (
        role === "starting"
    ) {

        return "Starter";

    }


    if (
        role === "substitute"
    ) {

        return "Udskifter";

    }


    if (
        role === "selected"
    ) {

        return "Udtaget";

    }


    return "Ikke udtaget";

}


function start11Escape(
    value
) {

    if (
        typeof escapeHTML === "function"
    ) {

        return escapeHTML(
            value ?? ""
        );

    }


    const div =
        document.createElement(
            "div"
        );


    div.textContent =
        value ?? "";


    return div.innerHTML;

}


function start11GetVisibleSquad() {

    const search =
        (
            document.getElementById(
                "squadSearchInput"
            )?.value ||
            ""
        )
            .trim()
            .toLocaleLowerCase("da-DK");


    const position =
        document.getElementById(
            "squadPositionFilter"
        )?.value ||
        "";


    const status =
        document.getElementById(
            "squadStatusFilter"
        )?.value ||
        "";


    return start11FullSquad
        .filter(
            player => {

                if (
                    search &&
                    !String(
                        player.name || ""
                    )
                        .toLocaleLowerCase("da-DK")
                        .includes(search)
                ) {

                    return false;

                }


                if (
                    position &&
                    player.position !==
                        position
                ) {

                    return false;

                }


                if (
                    status &&
                    player.status !==
                        status
                ) {

                    return false;

                }


                return true;

            }
        )
        .sort(
            (a, b) => {

                const numberA =
                    Number(
                        a.number
                    );


                const numberB =
                    Number(
                        b.number
                    );


                if (
                    Number.isFinite(numberA) &&
                    Number.isFinite(numberB) &&
                    numberA !== numberB
                ) {

                    return numberA -
                        numberB;

                }


                return String(
                    a.name || ""
                ).localeCompare(
                    String(
                        b.name || ""
                    ),
                    "da"
                );

            }
        );

}


function start11RenderFullSquad() {

    const list =
        document.getElementById(
            "fullSquadList"
        );


    const count =
        document.getElementById(
            "fullSquadCount"
        );


    if (
        !list
    ) {

        return;

    }


    if (
        count
    ) {

        count.textContent =
            String(
                start11FullSquad.length
            );

    }


    const players =
        start11GetVisibleSquad();


    list.innerHTML =
        "";


    if (
        !players.length
    ) {

        list.innerHTML = `
            <div class="start11-help-text">
                Ingen spillere matcher filteret.
            </div>
        `;

        return;

    }


    players.forEach(
        player => {

            const row =
                document.createElement(
                    "div"
                );


            row.className =
                "full-squad-row" +
                (
                    player.selected
                        ? ""
                        : " not-selected"
                );


            row.dataset.playerId =
                player.id;


            row.innerHTML = `

                <span class="squad-no">
                    ${start11Escape(player.number || "—")}
                </span>

                <span class="squad-name">
                    ${start11Escape(player.name)}
                </span>

                <span class="squad-pos">
                    ${start11Escape(player.position)}
                </span>

                <span class="squad-status-pill ${start11Escape(player.status)}">
                    ${start11Escape(start11StatusLabel(player.status))}
                </span>

            `;


            row.addEventListener(
                "click",
                () => {

                    start11OpenSquadPlayerModal(
                        player.id
                    );

                }
            );


            list.appendChild(
                row
            );

        }
    );

}


function start11PlayersForSquadView() {

    if (
        start11SquadView ===
        "notSelected"
    ) {

        return start11FullSquad.filter(
            player =>
                !player.selected
        );

    }


    if (
        start11SquadView ===
        "all"
    ) {

        return [
            ...start11FullSquad
        ];

    }


    return start11FullSquad.filter(
        player =>
            player.selected ||
            start11GetPlayerRole(player) ===
                "starting" ||
            start11GetPlayerRole(player) ===
                "substitute"
    );

}


function start11RenderMatchSquad() {

    const list =
        document.getElementById(
            "matchSquadOverview"
        );


    const count =
        document.getElementById(
            "matchSquadCount"
        );


    const heading =
        document.getElementById(
            "matchSquadHeading"
        );


    if (
        !list
    ) {

        return;

    }


    const players =
        start11PlayersForSquadView();


    if (
        count
    ) {

        count.textContent =
            String(
                players.length
            );

    }


    if (
        heading
    ) {

        heading.textContent =
            start11SquadView === "all"
                ? "TRUP"
                : start11SquadView === "notSelected"
                    ? "IKKE UDTAGET"
                    : "KAMPTRUP";

    }


    list.innerHTML =
        "";


    players
        .sort(
            (a, b) => {

                const roleOrder = {
                    starting: 0,
                    substitute: 1,
                    selected: 2,
                    "not-selected": 3
                };


                const roleA =
                    start11GetPlayerRole(a);


                const roleB =
                    start11GetPlayerRole(b);


                if (
                    roleOrder[roleA] !==
                    roleOrder[roleB]
                ) {

                    return (
                        roleOrder[roleA] -
                        roleOrder[roleB]
                    );

                }


                return String(
                    a.name || ""
                ).localeCompare(
                    String(
                        b.name || ""
                    ),
                    "da"
                );

            }
        )
        .forEach(
            player => {

                const role =
                    start11GetPlayerRole(
                        player
                    );


                const row =
                    document.createElement(
                        "div"
                    );


                row.className =
                    "squad-overview-row";


                row.innerHTML = `

                    <span class="squad-overview-check">
                        ${player.selected || role !== "not-selected" ? "✓" : ""}
                    </span>

                    <span class="squad-overview-number">
                        ${start11Escape(player.number || "—")}
                    </span>

                    <span class="squad-overview-name">
                        ${start11Escape(player.name)}
                    </span>

                    <span class="squad-overview-position">
                        ${start11Escape(player.position)}
                    </span>

                    <span class="squad-role-pill ${start11Escape(role)}">
                        ${start11Escape(start11RoleLabel(role))}
                    </span>

                `;


                row.addEventListener(
                    "click",
                    () => {

                        start11ToggleSelection(
                            player.id
                        );

                    }
                );


                list.appendChild(
                    row
                );

            }
        );

}


function start11ToggleSelection(
    id
) {

    const player =
        start11FullSquad.find(
            item =>
                item.id === id
        );


    if (
        !player
    ) {

        return;

    }


    const role =
        start11GetPlayerRole(
            player
        );


    /*
        En spiller, der allerede står på banen
        eller bænken, skal ikke "forsvinde"
        ved et simpelt klik. Flyt spilleren ud
        via den eksisterende lineup-editor først.
    */

    if (
        role === "starting" ||
        role === "substitute"
    ) {

        if (
            typeof visNotification ===
            "function"
        ) {

            visNotification(
                "Spilleren er allerede i kampens opstilling. Flyt/fjern spilleren fra opstillingen først."
            );

        }

        return;

    }


    if (
        player.status !==
        "available"
    ) {

        if (
            typeof visNotification ===
            "function"
        ) {

            visNotification(
                "Spilleren kan ikke udtages, før status er Tilgængelig."
            );

        }

        return;

    }


    player.selected =
        !player.selected;


    start11SaveFullSquad();

    start11RenderSquadUI();

}


function start11OpenSquadPlayerModal(
    id = null
) {

    const modal =
        document.getElementById(
            "squadPlayerModal"
        );


    if (
        !modal
    ) {

        return;

    }


    start11EditingSquadPlayerId =
        id;


    const player =
        id
            ? start11FullSquad.find(
                item =>
                    item.id === id
            )
            : null;


    const setValue =
        (
            elementId,
            value
        ) => {

            const element =
                document.getElementById(
                    elementId
                );


            if (
                element
            ) {

                element.value =
                    value ?? "";

            }

        };


    setValue(
        "squadPlayerName",
        player?.name || ""
    );


    setValue(
        "squadPlayerNumber",
        player?.number || ""
    );


    setValue(
        "squadPlayerPosition",
        player?.position || "CM"
    );


    setValue(
        "squadPlayerStatus",
        player?.status || "available"
    );


    const selected =
        document.getElementById(
            "squadPlayerSelected"
        );


    if (
        selected
    ) {

        selected.checked =
            Boolean(
                player?.selected
            );

    }


    const title =
        document.getElementById(
            "squadPlayerModalTitle"
        );


    if (
        title
    ) {

        title.textContent =
            player
                ? "REDIGER SPILLER"
                : "TILFØJ SPILLER";

    }


    const deleteButton =
        document.getElementById(
            "deleteSquadPlayerButton"
        );


    if (
        deleteButton
    ) {

        deleteButton.style.display =
            player
                ? "inline-flex"
                : "none";

    }


    modal.style.display =
        "flex";

}


function start11CloseSquadPlayerModal() {

    const modal =
        document.getElementById(
            "squadPlayerModal"
        );


    if (
        modal
    ) {

        modal.style.display =
            "none";

    }


    start11EditingSquadPlayerId =
        null;

}


function start11SaveSquadPlayerFromModal() {

    const name =
        document.getElementById(
            "squadPlayerName"
        )?.value.trim() ||
        "";


    if (
        !name
    ) {

        if (
            typeof visNotification ===
            "function"
        ) {

            visNotification(
                "Indtast spillerens navn."
            );

        }

        return;

    }


    const number =
        document.getElementById(
            "squadPlayerNumber"
        )?.value.trim() ||
        "";


    const position =
        document.getElementById(
            "squadPlayerPosition"
        )?.value ||
        "CM";


    const status =
        document.getElementById(
            "squadPlayerStatus"
        )?.value ||
        "available";


    const selected =
        Boolean(
            document.getElementById(
                "squadPlayerSelected"
            )?.checked
        );


    if (
        start11EditingSquadPlayerId
    ) {

        const player =
            start11FullSquad.find(
                item =>
                    item.id ===
                    start11EditingSquadPlayerId
            );


        if (
            player
        ) {

            player.name =
                name;

            player.number =
                number;

            player.position =
                position;

            player.status =
                status;

            player.selected =
                status === "available"
                    ? selected
                    : false;

        }

    } else {

        start11FullSquad.push({

            id:
                start11MakeId(),

            name,

            number,

            position,

            status,

            selected:
                status === "available"
                    ? selected
                    : false

        });

    }


    start11SaveFullSquad();

    start11CloseSquadPlayerModal();

    start11RenderSquadUI();


    if (
        typeof visNotification ===
        "function"
    ) {

        visNotification(
            `${name} er gemt i truppen`
        );

    }

}


function start11DeleteSquadPlayer() {

    if (
        !start11EditingSquadPlayerId
    ) {

        return;

    }


    const player =
        start11FullSquad.find(
            item =>
                item.id ===
                start11EditingSquadPlayerId
        );


    if (
        !player
    ) {

        return;

    }


    const role =
        start11GetPlayerRole(
            player
        );


    if (
        role === "starting" ||
        role === "substitute"
    ) {

        if (
            typeof visNotification ===
            "function"
        ) {

            visNotification(
                "Spilleren er i kampens opstilling. Fjern spilleren dér først."
            );

        }

        return;

    }


    start11FullSquad =
        start11FullSquad.filter(
            item =>
                item.id !==
                start11EditingSquadPlayerId
        );


    start11SaveFullSquad();

    start11CloseSquadPlayerModal();

    start11RenderSquadUI();

}


