function start11SaveDbuUrl() {

    const input =
        document.getElementById(
            "dbuTeamUrlInput"
        );


    const status =
        document.getElementById(
            "dbuConnectionStatus"
        );


    const value =
        input?.value.trim() ||
        "";


    if (
        !value
    ) {

        localStorage.removeItem(
            START11_DBU_URL_KEY
        );


        if (
            status
        ) {

            status.textContent =
                "Ikke forbundet";

        }


        return;

    }


    try {

        const url =
            new URL(value);


        if (
            !url.hostname
                .toLowerCase()
                .endsWith("dbu.dk")
        ) {

            throw new Error(
                "DBU-link forventes."
            );

        }


        localStorage.setItem(
            START11_DBU_URL_KEY,
            url.href
        );


        if (
            status
        ) {

            status.textContent =
                "DBU-link gemt – klar til automatisk sync";

        }


        if (
            typeof visNotification ===
            "function"
        ) {

            visNotification(
                "DBU-holdlink gemt."
            );

        }

    } catch (error) {

        if (
            typeof visNotification ===
            "function"
        ) {

            visNotification(
                "Indsæt et gyldigt DBU-link."
            );

        }

    }

}


function start11OpenDbuUrl() {

    const value =
        localStorage.getItem(
            START11_DBU_URL_KEY
        ) ||
        document.getElementById(
            "dbuTeamUrlInput"
        )?.value.trim();


    if (
        !value
    ) {

        if (
            typeof visNotification ===
            "function"
        ) {

            visNotification(
                "Gem først jeres DBU-holdlink."
            );

        }

        return;

    }


    window.open(
        value,
        "_blank",
        "noopener"
    );

}


