async function start11V8SubmitClubTeamModal() {

    if (
        start11V8ModalMode ===
        "club"
    ) {

        const input =
            document.getElementById(
                "start11NewClubNameV8"
            );


        const name =
            input?.value?.trim();


        if (!name) {

            input?.focus();

            return;

        }


        const club =
            start11V8CreateClub(
                name
            );


        start11V8CloseClubTeamModal();


        /*
            Når klubben er oprettet, åbner vi straks
            "Tilføj hold", så flowet bliver hurtigt.
        */
        setTimeout(
            () =>
                start11V8OpenTeamModal(
                    club?.name ||
                    name
                ),
            120
        );


        return;

    }


    const clubSelect =
        document.getElementById(
            "start11NewTeamClubV8"
        );


    const teamInput =
        document.getElementById(
            "start11NewTeamNameV8"
        );


    const clubName =
        clubSelect?.value?.trim();


    const teamName =
        teamInput?.value?.trim();


    if (
        !clubName ||
        !teamName
    ) {

        teamInput?.focus();

        return;

    }


    const duplicate =
        cloudTeams.some(
            team => {

                const meta =
                    start11V8GetTeamMeta(
                        team
                    );


                return (
                    meta.clubName
                        .toLowerCase() ===
                    clubName
                        .toLowerCase() &&
                    meta.teamName
                        .toLowerCase() ===
                    teamName
                        .toLowerCase()
                );

            }
        );


    if (duplicate) {

        visNotification(
            "Det hold findes allerede under klubben."
        );

        return;

    }


    const save =
        document.getElementById(
            "start11SaveClubTeamV8"
        );


    if (save) {

        save.disabled =
            true;

        save.textContent =
            "OPRETTER...";

    }


    await start11V8CreateBlankTeam(
        clubName,
        teamName
    );


    if (save) {

        save.disabled =
            false;

        save.textContent =
            "+ OPRET HOLD";

    }


    start11V8CloseClubTeamModal();

}


/* =========================================================
   NY TOPBAR KLUB / HOLD SELECTOR
========================================================= */

function start11V8EnsureClubTeamSelector() {

    const controls =
        document.getElementById(
            "teamControls"
        );


    const oldSelector =
        document.getElementById(
            "teamSelector"
        );


    if (
        !controls ||
        !oldSelector
    ) {

        return;

    }


    oldSelector.style.display =
        "none";


    if (
        document.getElementById(
            "start11ClubTeamSwitcherV8"
        )
    ) {

        return;

    }


    const shell =
        document.createElement(
            "div"
        );


    shell.id =
        "start11ClubTeamSwitcherV8";

    shell.className =
        "start11-v8-switcher";


    shell.innerHTML = `
        <button
            type="button"
            class="start11-v8-switcher-button"
            id="start11ClubTeamSwitcherButtonV8"
            aria-haspopup="true"
            aria-expanded="false"
        >
            <span class="start11-v8-switcher-club">
                KLUB
            </span>

            <span class="start11-v8-switcher-divider">
                /
            </span>

            <strong class="start11-v8-switcher-team">
                HOLD
            </strong>

            <span class="start11-v8-switcher-chevron">
                ▾
            </span>
        </button>

        <div
            class="start11-v8-switcher-menu"
            id="start11ClubTeamSwitcherMenuV8"
        ></div>
    `;


    controls.insertBefore(
        shell,
        oldSelector
    );


    document
        .getElementById(
            "start11ClubTeamSwitcherButtonV8"
        )
        ?.addEventListener(
            "click",
            event => {

                event.stopPropagation();

                start11V8ToggleClubTeamMenu();

            }
        );


    document.addEventListener(
        "click",
        event => {

            if (
                !shell.contains(
                    event.target
                )
            ) {

                start11V8CloseClubTeamMenu();

            }

        }
    );


    /*
        Erstat + HOLD-knappen, så den ikke bruger
        den gamle "kopiér det aktive hold"-funktion.
    */
    const oldNewTeam =
        document.getElementById(
            "newTeamButton"
        );


    if (
        oldNewTeam &&
        oldNewTeam.dataset.v8Replaced !==
            "1"
    ) {

        const clone =
            oldNewTeam.cloneNode(
                true
            );


        clone.dataset.v8Replaced =
            "1";

        clone.textContent =
            "+ HOLD";


        oldNewTeam.replaceWith(
            clone
        );


        clone.addEventListener(
            "click",
            () => {

                const meta =
                    start11V8GetActiveMeta();


                start11V8OpenTeamModal(
                    meta.clubName
                );

            }
        );

    }

}


function start11V8RenderClubTeamSelector() {

    start11V8EnsureClubTeamSelector();


    const active =
        start11V8GetActiveMeta();


    const button =
        document.getElementById(
            "start11ClubTeamSwitcherButtonV8"
        );


    if (button) {

        const club =
            button.querySelector(
                ".start11-v8-switcher-club"
            );


        const team =
            button.querySelector(
                ".start11-v8-switcher-team"
            );


        if (club) {

            club.textContent =
                active.clubName;

        }


        if (team) {

            team.textContent =
                active.teamName;

        }

    }


    const menu =
        document.getElementById(
            "start11ClubTeamSwitcherMenuV8"
        );


    if (!menu) {

        return;

    }


    menu.innerHTML =
        "";


    const clubs =
        start11V8GetAllClubs();


    clubs.forEach(
        club => {

            const group =
                document.createElement(
                    "div"
                );


            group.className =
                "start11-v8-menu-club";


            const heading =
                document.createElement(
                    "div"
                );


            heading.className =
                "start11-v8-menu-club-heading";


            heading.innerHTML = `
                <strong>
                    ${start11Escape(
                        club.name
                    )}
                </strong>

                <button
                    type="button"
                    class="start11-v8-inline-add"
                    aria-label="Tilføj hold"
                >
                    + HOLD
                </button>
            `;


            heading
                .querySelector(
                    ".start11-v8-inline-add"
                )
                ?.addEventListener(
                    "click",
                    event => {

                        event.stopPropagation();

                        start11V8CloseClubTeamMenu();

                        start11V8OpenTeamModal(
                            club.name
                        );

                    }
                );


            group.appendChild(
                heading
            );


            const teams =
                start11V8TeamsForClub(
                    club.name
                );


            if (!teams.length) {

                const empty =
                    document.createElement(
                        "div"
                    );


                empty.className =
                    "start11-v8-menu-empty";

                empty.textContent =
                    "Ingen hold endnu";


                group.appendChild(
                    empty
                );

            }


            teams.forEach(
                team => {

                    const meta =
                        start11V8GetTeamMeta(
                            team
                        );


                    const item =
                        document.createElement(
                            "button"
                        );


                    item.type =
                        "button";

                    item.className =
                        "start11-v8-menu-team" +
                        (
                            team.id ===
                            activeTeamId
                                ? " active"
                                : ""
                        );


                    item.innerHTML = `
                        <span
                            class="start11-v8-menu-check"
                        >
                            ${
                                team.id ===
                                activeTeamId
                                    ? "✓"
                                    : ""
                            }
                        </span>

                        <span>
                            ${start11Escape(
                                meta.teamName
                            )}
                        </span>
                    `;


                    item.addEventListener(
                        "click",
                        async () => {

                            start11V8CloseClubTeamMenu();


                            if (
                                team.id !==
                                activeTeamId
                            ) {

                                await changeTeam(
                                    team.id
                                );

                            }


                            start11V8RenderClubTeamSelector();

                        }
                    );


                    group.appendChild(
                        item
                    );

                }
            );


            menu.appendChild(
                group
            );

        }
    );


    const addClub =
        document.createElement(
            "button"
        );


    addClub.type =
        "button";

    addClub.className =
        "start11-v8-add-club-menu";

    addClub.textContent =
        "+ TILFØJ KLUB";


    addClub.addEventListener(
        "click",
        () => {

            start11V8CloseClubTeamMenu();

            start11V8OpenClubModal();

        }
    );


    menu.appendChild(
        addClub
    );

}


function start11V8ToggleClubTeamMenu() {

    const menu =
        document.getElementById(
            "start11ClubTeamSwitcherMenuV8"
        );


    const button =
        document.getElementById(
            "start11ClubTeamSwitcherButtonV8"
        );


    if (
        !menu ||
        !button
    ) {

        return;

    }


    const isOpen =
        menu.classList.toggle(
            "open"
        );


    button.setAttribute(
        "aria-expanded",
        isOpen
            ? "true"
            : "false"
    );

}


function start11V8CloseClubTeamMenu() {

    const menu =
        document.getElementById(
            "start11ClubTeamSwitcherMenuV8"
        );


    const button =
        document.getElementById(
            "start11ClubTeamSwitcherButtonV8"
        );


    menu?.classList.remove(
        "open"
    );


    button?.setAttribute(
        "aria-expanded",
        "false"
    );

}


/* =========================================================
   UPDATE EXISTING SELECTOR / HOLD-SKIFT
========================================================= */

if (
    typeof updateTeamSelector ===
    "function"
) {

    const updateTeamSelectorBeforeV8 =
        updateTeamSelector;


    updateTeamSelector =
        function (...args) {

            const result =
                updateTeamSelectorBeforeV8(
                    ...args
                );


            start11V8RenderClubTeamSelector();


            return result;

        };

}


if (
    typeof changeTeam ===
    "function"
) {

    const changeTeamBeforeV8 =
        changeTeam;


    changeTeam =
        async function (
            teamId
        ) {

            const result =
                await changeTeamBeforeV8(
                    teamId
                );


            /*
                V7 har allerede skiftet DBU/kalender.
                V8 opdaterer nu klub-/holdvælger og sikrer
                at hele truppen er det nye holds trup.
            */
            const team =
                start11V8GetActiveTeam();


            if (team) {

                applyTeamData(
                    team.data || {}
                );

            }


            start11V8RenderClubTeamSelector();

            renderTeamsDashboard();

            start11V8RenderLatestMatch();


            return result;

        };

}


