/* =========================================================
   SENESTE KAMP
========================================================= */

function start11V8FindLatestMatch() {

    let matches = [];


    if (
        typeof start11CalendarV3SortedMatches ===
        "function"
    ) {

        matches =
            start11CalendarV3SortedMatches();

    } else if (
        typeof start11CalendarAllMatches ===
        "function"
    ) {

        matches =
            start11CalendarAllMatches();

    }


    const now =
        new Date();


    return (
        (Array.isArray(matches)
            ? matches
            : [])
            .map(
                match =>
                    start11CalendarNormalizeMatch(
                        match
                    )
            )
            .filter(
                match => {

                    const date =
                        start11CalendarDateObject(
                            match
                        );


                    return (
                        date &&
                        date.getTime() <
                        now.getTime()
                    );

                }
            )
            .sort(
                (a, b) => {

                    const da =
                        start11CalendarDateObject(
                            a
                        );

                    const db =
                        start11CalendarDateObject(
                            b
                        );


                    return (
                        (db?.getTime() || 0) -
                        (da?.getTime() || 0)
                    );

                }
            )[0] ||
        null
    );

}


function start11V8ResultText(
    match
) {

    const raw =
        String(
            match?.result || ""
        )
            .trim()
            .replace(/\s+/g, " ");


    if (!raw) {

        return "—";

    }


    /*
        Behold DBU's resultat, men gør almindelige
        score-formater lidt mere læsevenlige.
    */
    const score =
        raw.match(
            /(\d+)\s*[-–:]\s*(\d+)/
        );


    if (score) {

        return (
            score[1] +
            " – " +
            score[2]
        );

    }


    return raw;

}


function start11V8EnsureLatestMatchCard() {

    const nextCard =
        document.querySelector(
            ".next-match-card"
        );


    const upcomingCard =
        document.querySelector(
            ".upcoming-card"
        );


    if (
        !nextCard ||
        !upcomingCard
    ) {

        return null;

    }


    let card =
        document.getElementById(
            "start11LatestMatchCardV8"
        );


    if (card) {

        return card;

    }


    card =
        document.createElement(
            "section"
        );


    card.id =
        "start11LatestMatchCardV8";

    card.className =
        "start11-card start11-v8-latest-card";


    upcomingCard.parentNode.insertBefore(
        card,
        upcomingCard
    );


    return card;

}


function start11V8RenderLatestMatch() {

    const card =
        start11V8EnsureLatestMatchCard();


    if (!card) {

        return;

    }


    const match =
        start11V8FindLatestMatch();


    if (!match) {

        card.style.display =
            "none";

        return;

    }


    card.style.display =
        "block";


    const normalized =
        start11CalendarNormalizeMatch(
            match
        );


    const dateText =
        start11CalendarFormatShortDate(
            normalized.date
        );


    const homeLogo =
        normalized.homeLogo ||
        "";

    const awayLogo =
        normalized.awayLogo ||
        "";


    card.innerHTML = `
        <div class="start11-v8-latest-heading">

            <div>
                <span class="start11-v8-latest-eyebrow">
                    SENESTE KAMP
                </span>

                <small>
                    ${start11Escape(
                        dateText
                    )}
                </small>
            </div>

            <button
                type="button"
                class="start11-v8-latest-calendar"
            >
                Kalender →
            </button>

        </div>

        <div class="start11-v8-latest-result-row">

            <div class="start11-v8-latest-team">
                ${
                    typeof start11V5LogoMarkup ===
                    "function"
                        ? start11V5LogoMarkup(
                            homeLogo,
                            normalized.home,
                            "latest"
                        )
                        : ""
                }

                <span>
                    ${start11Escape(
                        normalized.home ||
                        "Hjemmehold"
                    )}
                </span>
            </div>

            <strong class="start11-v8-latest-score">
                ${start11Escape(
                    start11V8ResultText(
                        normalized
                    )
                )}
            </strong>

            <div class="start11-v8-latest-team away">
                ${
                    typeof start11V5LogoMarkup ===
                    "function"
                        ? start11V5LogoMarkup(
                            awayLogo,
                            normalized.away,
                            "latest"
                        )
                        : ""
                }

                <span>
                    ${start11Escape(
                        normalized.away ||
                        "Udehold"
                    )}
                </span>
            </div>

        </div>
    `;


    if (
        typeof start11V5BindLogoFallbacks ===
        "function"
    ) {

        start11V5BindLogoFallbacks(
            card
        );

    }


    card
        .querySelector(
            ".start11-v8-latest-calendar"
        )
        ?.addEventListener(
            "click",
            () => {

                if (
                    typeof start11CalendarOpen ===
                    "function"
                ) {

                    start11CalendarOpen(
                        normalized.date
                    );

                    return;

                }


                const calendarButton =
                    document.getElementById(
                        "start11CalendarHeaderButton"
                    );


                calendarButton?.click();

            }
        );

}


