/* =========================================================
   MÅLMANDSKLASSE PÅ UDSKIFTERE
========================================================= */

function start11V9MarkSubstituteKeepers() {

    document
        .querySelectorAll(
            "#substituteList .substitute"
        )
        .forEach(
            row => {

                const index =
                    Number(
                        row.dataset.index
                    );


                const player =
                    Array.isArray(
                        udskiftere
                    )
                        ? udskiftere[
                            index
                        ]
                        : null;


                row.classList.toggle(
                    "start11-v9-gk-substitute",
                    player?.position ===
                        "GK"
                );

            }
        );

}


if (
    typeof opdaterUdskiftere ===
    "function"
) {

    const opdaterUdskiftereBeforeV9 =
        opdaterUdskiftere;


    opdaterUdskiftere =
        function (...args) {

            const result =
                opdaterUdskiftereBeforeV9(
                    ...args
                );


            start11V9MarkSubstituteKeepers();


            return result;

        };

}


/* =========================================================
   AUTOMATISK KLUBLOGO FRA DBU
========================================================= */

function start11V9ReadMatches() {

    try {

        const parsed =
            JSON.parse(
                localStorage.getItem(
                    START11_MATCHES_KEY
                ) ||
                "[]"
            );


        return Array.isArray(parsed)
            ? parsed
            : [];

    } catch {

        return [];

    }

}


function start11V9IsUsableLogo(
    value
) {

    const logo =
        String(
            value || ""
        ).trim();


    if (!logo) {

        return false;

    }


    if (
        typeof start11V5IsGenericDbuLogo ===
        "function" &&
        start11V5IsGenericDbuLogo(
            logo
        )
    ) {

        return false;

    }


    const lower =
        logo.toLowerCase();


    return !(
        lower.includes(
            "dbu-logo"
        ) ||
        lower.includes(
            "favicon"
        ) ||
        lower.includes(
            "apple-touch-icon"
        )
    );

}


/*
    DBU-holdet er det holdnavn, der går igen flest gange
    i det hentede kampprogram.

    Det virker både når START11-holdet spiller hjemme og ude,
    og kræver ikke at brugeren kalder holdet præcis det samme
    som DBU gør.
*/
function start11V9InferTrackedDbuTeam() {

    const matches =
        start11V9ReadMatches();


    if (!matches.length) {

        return null;

    }


    const counts =
        new Map();


    const logos =
        new Map();


    const add =
        (
            name,
            logo
        ) => {

            const cleanName =
                String(
                    name || ""
                ).trim();


            if (!cleanName) {

                return;

            }


            const key =
                typeof start11V5NormalizeTeamKey ===
                    "function"
                    ? start11V5NormalizeTeamKey(
                        cleanName
                    )
                    : cleanName
                        .toLowerCase();


            counts.set(
                key,
                {
                    name:
                        cleanName,
                    count:
                        (
                            counts.get(
                                key
                            )?.count ||
                            0
                        ) +
                        1
                }
            );


            if (
                start11V9IsUsableLogo(
                    logo
                ) &&
                !logos.has(
                    key
                )
            ) {

                logos.set(
                    key,
                    logo
                );

            }

        };


    matches.forEach(
        rawMatch => {

            let match =
                rawMatch;


            if (
                typeof start11CalendarNormalizeMatch ===
                "function"
            ) {

                match =
                    start11CalendarNormalizeMatch(
                        rawMatch
                    );

            }


            add(
                match.home ||
                match.homeTeam,
                match.homeLogo
            );


            add(
                match.away ||
                match.awayTeam,
                match.awayLogo
            );

        }
    );


    const sorted =
        [...counts.entries()]
            .sort(
                (a, b) =>
                    b[1].count -
                    a[1].count
            );


    if (!sorted.length) {

        return null;

    }


    const [
        key,
        info
    ] =
        sorted[0];


    return {
        name:
            info.name,

        logo:
            logos.get(
                key
            ) ||
            ""
    };

}


function start11V9SyncLogoFromDbu(
    persist = true
) {

    const dbuTeam =
        start11V9InferTrackedDbuTeam();


    if (
        !dbuTeam ||
        !start11V9IsUsableLogo(
            dbuTeam.logo
        )
    ) {

        start11V9RefreshSwitcherLogo();

        return "";

    }


    const current =
        start11V9GetActiveTheme();


    /*
        DBU-logo må gerne opdateres automatisk.
        Et eventuelt fremtidigt manuelt logo kan markeres
        med logoSource = "manual" og bliver så ikke overskrevet.
    */
    if (
        current.logoSource ===
        "manual"
    ) {

        start11V9RefreshSwitcherLogo();

        return current.logo;

    }


    if (
        current.logo !==
            dbuTeam.logo ||
        current.logoSource !==
            "dbu"
    ) {

        current.logo =
            dbuTeam.logo;

        current.logoSource =
            "dbu";


        start11V9SetThemeOnActiveTeam(
            current,
            persist
        );

    } else {

        start11V9RefreshSwitcherLogo();

    }


    return current.logo;

}


/* =========================================================
   LOGO I KLUB / HOLD SWITCHER
========================================================= */

function start11V9EnsureSwitcherLogo() {

    const button =
        document.getElementById(
            "start11ClubTeamSwitcherButtonV8"
        );


    if (!button) {

        return null;

    }


    let wrapper =
        button.querySelector(
            ".start11-v9-switcher-logo"
        );


    if (!wrapper) {

        wrapper =
            document.createElement(
                "span"
            );


        wrapper.className =
            "start11-v9-switcher-logo";


        const clubText =
            button.querySelector(
                ".start11-v8-switcher-club"
            );


        button.insertBefore(
            wrapper,
            clubText ||
            button.firstChild
        );

    }


    return wrapper;

}


function start11V9ClubInitials() {

    const meta =
        typeof start11V8GetActiveMeta ===
            "function"
            ? start11V8GetActiveMeta()
            : {
                clubName:
                    "S11"
            };


    const words =
        String(
            meta.clubName ||
            "S11"
        )
            .trim()
            .split(/\s+/)
            .filter(Boolean);


    if (!words.length) {

        return "S11";

    }


    if (
        words.length === 1
    ) {

        return words[0]
            .slice(0, 2)
            .toUpperCase();

    }


    return (
        words[0][0] +
        words[1][0]
    ).toUpperCase();

}


function start11V9RefreshSwitcherLogo() {

    const wrapper =
        start11V9EnsureSwitcherLogo();


    if (!wrapper) {

        return;

    }


    const theme =
        start11V9GetActiveTheme();


    const logo =
        start11V9IsUsableLogo(
            theme.logo
        )
            ? theme.logo
            : "";


    wrapper.innerHTML =
        "";


    if (logo) {

        const image =
            document.createElement(
                "img"
            );


        image.alt =
            "";

        image.src =
            logo;


        image.addEventListener(
            "error",
            () => {

                wrapper.innerHTML =
                    `<span>${
                        start11Escape(
                            start11V9ClubInitials()
                        )
                    }</span>`;

            },
            {
                once: true
            }
        );


        wrapper.appendChild(
            image
        );

    } else {

        wrapper.innerHTML =
            `<span>${
                start11Escape(
                    start11V9ClubInitials()
                )
            }</span>`;

    }

}


/*
    V8 renderer topbaren igen ved holdskift.
    V9 lægger logoet tilbage efter hver rendering.
*/
if (
    typeof start11V8RenderClubTeamSelector ===
    "function"
) {

    const start11V8RenderClubTeamSelectorBeforeV9 =
        start11V8RenderClubTeamSelector;


    start11V8RenderClubTeamSelector =
        function (...args) {

            const result =
                start11V8RenderClubTeamSelectorBeforeV9(
                    ...args
                );


            start11V9RefreshSwitcherLogo();


            return result;

        };

}


/* =========================================================
   ACCOUNT DROPDOWN: DESIGN & FARVER
========================================================= */

function start11V9InstallDesignMenuItem() {

    if (
        document.getElementById(
            "designColorsMenuButtonV9"
        )
    ) {

        return;

    }


    const reference =
        document.getElementById(
            "accountSettingsMenuButton"
        ) ||
        document.getElementById(
            "helpSupportMenuButton"
        );


    const menu =
        reference?.parentElement;


    if (
        !reference ||
        !menu
    ) {

        return;

    }


    const button =
        document.createElement(
            "button"
        );


    button.id =
        "designColorsMenuButtonV9";

    button.type =
        "button";

    button.className =
        "account-dropdown-item";


    button.innerHTML = `
        <span
            class="account-dropdown-icon start11-v9-design-icon"
        ></span>

        <span>
            Design & farver
        </span>

        <span
            class="account-dropdown-arrow"
        >
            ›
        </span>
    `;


    menu.insertBefore(
        button,
        reference
    );


    button.addEventListener(
        "click",
        () => {

            if (
                typeof closeAccountDropdown ===
                "function"
            ) {

                closeAccountDropdown();

            }


            start11V9OpenThemeModal();

        }
    );

}


