/* =========================================================
   MODAL
========================================================= */

function start11V12EnsureModal() {

    if (
        document.getElementById(
            "start11UnifiedPlayerModalV12"
        )
    ) {

        return;

    }


    const modal =
        document.createElement(
            "div"
        );


    modal.id =
        "start11UnifiedPlayerModalV12";

    modal.className =
        "modal";


    modal.innerHTML = `
        <div
            class="
                modal-content
                s11v12-shell
            "
        >

            <header
                id="s11v12Top"
                class="s11v12-top"
            ></header>

            <nav
                id="s11v12Tabs"
                class="s11v12-tabs"
            ></nav>

            <div class="s11v12-main">

                <main
                    id="s11v12Content"
                    class="s11v12-content"
                ></main>

                <aside
                    id="s11v12Side"
                    class="s11v12-side"
                ></aside>

            </div>

        </div>
    `;


    document.body.appendChild(
        modal
    );


    modal.addEventListener(
        "mousedown",
        event => {

            if (
                event.target ===
                modal
            ) {

                start11V12Close();

            }

        }
    );

}


/* =========================================================
   OPEN / CLOSE
========================================================= */

function start11V12Open(
    playerId = null
) {

    start11V12EnsureModal();


    start11V12IsNew =
        !playerId;


    if (
        playerId
    ) {

        const player =
            start11FullSquad.find(
                item =>
                    item.id ===
                    playerId
            );


        if (!player) {

            return;

        }


        start11V12PlayerId =
            player.id;


        start11V12ProfileDraft =
            start11V12Clone(
                player
            );


        start11V12DevelopmentDraft =
            start11V12NormalizeDevelopment(
                player.development
            );

    } else {

        const fresh =
            start11V12DefaultProfile();


        start11V12PlayerId =
            fresh.id;


        start11V12ProfileDraft =
            start11V12Clone(
                fresh
            );


        start11V12DevelopmentDraft =
            start11V12NormalizeDevelopment(
                fresh.development
            );

    }


    start11V12Tab =
        "profile";


    start11V12Render();


    document.getElementById(
        "start11UnifiedPlayerModalV12"
    )
        .style.display =
        "flex";

}


function start11V12Close() {

    const modal =
        document.getElementById(
            "start11UnifiedPlayerModalV12"
        );


    if (modal) {

        modal.style.display =
            "none";

    }


    start11V12PlayerId =
        null;

    start11V12ProfileDraft =
        null;

    start11V12DevelopmentDraft =
        null;

    start11V12IsNew =
        false;

}


/* =========================================================
   MATCH SYNC AFTER PROFILE EDIT
========================================================= */

function start11V12SyncEditedProfileToMatch(
    savedPlayer
) {

    const sync =
        matchPlayer => {

            if (!matchPlayer) {

                return;

            }


            const same =
                matchPlayer.squadId ===
                    savedPlayer.id ||
                (
                    typeof start11SamePlayer ===
                        "function" &&
                    start11SamePlayer(
                        matchPlayer,
                        savedPlayer
                    )
                );


            if (!same) {

                return;

            }


            matchPlayer.squadId =
                savedPlayer.id;

            matchPlayer.name =
                savedPlayer.name;

            matchPlayer.number =
                savedPlayer.number;

            matchPlayer.position =
                savedPlayer.position;

            matchPlayer.strengths =
                savedPlayer.strengths ||
                "";

            matchPlayer.weaknesses =
                savedPlayer.weaknesses ||
                "";

            matchPlayer.focusWithBall =
                savedPlayer.focusWithBall ||
                "";

            matchPlayer.focusWithoutBall =
                savedPlayer.focusWithoutBall ||
                "";

            matchPlayer.video =
                savedPlayer.video ||
                "";

        };


    if (
        Array.isArray(
            spillere
        )
    ) {

        spillere.forEach(
            sync
        );

    }


    if (
        Array.isArray(
            udskiftere
        )
    ) {

        udskiftere.forEach(
            sync
        );

    }


    if (
        typeof gemAlt ===
        "function"
    ) {

        gemAlt();

    }


    if (
        typeof tegnOpstilling ===
        "function"
    ) {

        tegnOpstilling();

    }


    if (
        typeof opdaterUdskiftere ===
        "function"
    ) {

        opdaterUdskiftere();

    }

}


/* =========================================================
   SAVE / DELETE
========================================================= */

function start11V12Save(
    closeAfter = false
) {

    const name =
        String(
            start11V12ProfileDraft
                ?.name ||
            ""
        ).trim();


    if (!name) {

        if (
            typeof visNotification ===
            "function"
        ) {

            visNotification(
                "Indtast spillerens navn."
            );

        }


        start11V12Tab =
            "profile";

        start11V12Render();

        return false;

    }


    start11V12ProfileDraft.name =
        name;

    start11V12ProfileDraft.development =
        start11V12NormalizeDevelopment(
            start11V12DevelopmentDraft
        );


    let savedPlayer;


    if (
        start11V12IsNew
    ) {

        savedPlayer =
            start11V12Clone(
                start11V12ProfileDraft
            );


        start11FullSquad.push(
            savedPlayer
        );


        start11V12IsNew =
            false;

        start11V12PlayerId =
            savedPlayer.id;

    } else {

        const index =
            start11FullSquad.findIndex(
                item =>
                    item.id ===
                    start11V12PlayerId
            );


        if (
            index === -1
        ) {

            return false;

        }


        const old =
            start11FullSquad[
                index
            ];


        savedPlayer = {
            ...old,
            ...start11V12Clone(
                start11V12ProfileDraft
            ),

            development:
                start11V12NormalizeDevelopment(
                    start11V12DevelopmentDraft
                )
        };


        if (
            savedPlayer.status !==
            "available"
        ) {

            savedPlayer.selected =
                false;

        }


        start11FullSquad[
            index
        ] =
            savedPlayer;

    }


    start11V12ProfileDraft =
        start11V12Clone(
            savedPlayer
        );


    start11V12DevelopmentDraft =
        start11V12NormalizeDevelopment(
            savedPlayer.development
        );


    if (
        typeof start11SaveFullSquad ===
        "function"
    ) {

        start11SaveFullSquad();

    }


    start11V12SyncEditedProfileToMatch(
        savedPlayer
    );


    if (
        typeof start11RenderSquadUI ===
        "function"
    ) {

        start11RenderSquadUI();

    }


    if (
        typeof scheduleCloudSave ===
        "function"
    ) {

        scheduleCloudSave();

    }


    if (
        typeof visNotification ===
        "function"
    ) {

        visNotification(
            `${savedPlayer.name} er gemt.`
        );

    }


    if (
        closeAfter
    ) {

        start11V12Close();

    } else {

        start11V12Render();

    }


    return true;

}


function start11V12Delete() {

    if (
        start11V12IsNew
    ) {

        start11V12Close();

        return;

    }


    const player =
        start11FullSquad.find(
            item =>
                item.id ===
                start11V12PlayerId
        );


    if (!player) {

        return;

    }


    if (
        typeof start11GetPlayerRole ===
            "function"
    ) {

        const role =
            start11GetPlayerRole(
                player
            );


        if (
            role === "starting" ||
            role === "substitute"
        ) {

            if (
                typeof visNotification ===
                "function"
            ) {

                visNotification(
                    "Spilleren er i kampens opstilling. Fjern spilleren fra opstillingen først."
                );

            }


            return;

        }

    }


    if (
        !window.confirm(
            `Slet ${player.name}?`
        )
    ) {

        return;

    }


    start11FullSquad =
        start11FullSquad.filter(
            item =>
                item.id !==
                start11V12PlayerId
        );


    if (
        typeof start11SaveFullSquad ===
        "function"
    ) {

        start11SaveFullSquad();

    }


    if (
        typeof start11RenderSquadUI ===
        "function"
    ) {

        start11RenderSquadUI();

    }


    start11V12Close();

}


/* =========================================================
   RENDER
========================================================= */

function start11V12Render() {

    start11V12RenderTop();

    start11V12RenderTabs();

    start11V12RenderContent();

    start11V12RenderSide();

}


