function start11V12RenderAttributes(
    target
) {

    const attributes =
        start11V12DevelopmentDraft
            .attributes ||
        [];


    target.innerHTML = `

        <section class="s11v12-panel">

            <div class="s11v12-panel-head">

                <div>
                    <strong>ATTRIBUTES 1–100</strong>

                    <div
                        class="s11v12-muted"
                        style="margin-top:4px;"
                    >
                        Opret selv de attributes du bruger.
                        Vælg op til 8 til radardiagrammet.
                    </div>
                </div>

                <button
                    id="s11v12AddAttr"
                    class="s11v12-btn"
                    type="button"
                >
                    + ATTRIBUTE
                </button>

            </div>


            <div
                id="s11v12Attrs"
                class="s11v12-attrs"
            >
                ${
                    attributes
                        .map(
                            attribute => `
                                <div
                                    class="s11v12-attr"
                                    data-id="${
                                        start11V12Escape(
                                            attribute.id
                                        )
                                    }"
                                >

                                    <div class="s11v12-attr-main">

                                        <input
                                            class="s11v12-input"
                                            data-field="name"
                                            value="${
                                                start11V12Escape(
                                                    attribute.name
                                                )
                                            }"
                                        >

                                        <select
                                            class="s11v12-select"
                                            data-field="category"
                                        >
                                            ${
                                                [
                                                    "Teknisk",
                                                    "Taktisk",
                                                    "Fysisk",
                                                    "Mentalt",
                                                    "Målmand",
                                                    "Andet"
                                                ]
                                                    .map(
                                                        category => `
                                                            <option
                                                                ${
                                                                    attribute.category ===
                                                                    category
                                                                        ? "selected"
                                                                        : ""
                                                                }
                                                            >
                                                                ${category}
                                                            </option>
                                                        `
                                                    )
                                                    .join(
                                                        ""
                                                    )
                                            }
                                        </select>

                                    </div>


                                    <div>

                                        <input
                                            class="s11v12-range"
                                            data-field="rating"
                                            type="range"
                                            min="1"
                                            max="100"
                                            value="${
                                                Number(
                                                    attribute.rating ||
                                                    1
                                                )
                                            }"
                                        >

                                        <label
                                            class="s11v12-muted"
                                            style="
                                                display:flex;
                                                gap:5px;
                                                align-items:center;
                                                margin-top:5px;
                                            "
                                        >
                                            <input
                                                type="checkbox"
                                                data-field="radar"
                                                ${
                                                    attribute.radar !==
                                                    false
                                                        ? "checked"
                                                        : ""
                                                }
                                            >
                                            På radar
                                        </label>

                                    </div>


                                    <div
                                        class="s11v12-rating"
                                        data-value
                                    >
                                        ${
                                            Number(
                                                attribute.rating ||
                                                1
                                            )
                                        }
                                    </div>


                                    <button
                                        class="s11v12-del"
                                        type="button"
                                        data-delete
                                    >
                                        ×
                                    </button>

                                </div>
                            `
                        )
                        .join(
                            ""
                        )
                }
            </div>

        </section>
    `;


    target.querySelectorAll(
        ".s11v12-attr"
    )
        .forEach(
            row => {

                const id =
                    row.dataset.id;


                const item =
                    () =>
                        start11V12DevelopmentDraft
                            .attributes
                            .find(
                                attribute =>
                                    attribute.id ===
                                    id
                            );


                row.querySelector(
                    '[data-field="name"]'
                )
                    ?.addEventListener(
                        "input",
                        event => {

                            const current =
                                item();


                            if (!current) {

                                return;

                            }


                            current.name =
                                event.target.value;


                            start11V12RenderSide();

                        }
                    );


                row.querySelector(
                    '[data-field="category"]'
                )
                    ?.addEventListener(
                        "change",
                        event => {

                            const current =
                                item();


                            if (current) {

                                current.category =
                                    event.target.value;

                            }

                        }
                    );


                row.querySelector(
                    '[data-field="rating"]'
                )
                    ?.addEventListener(
                        "input",
                        event => {

                            const current =
                                item();


                            if (!current) {

                                return;

                            }


                            current.rating =
                                Math.max(
                                    1,
                                    Math.min(
                                        100,
                                        Number(
                                            event.target
                                                .value
                                        )
                                    )
                                );


                            row.querySelector(
                                "[data-value]"
                            )
                                .textContent =
                                current.rating;


                            start11V12RenderTop();

                            start11V12RenderSide();

                        }
                    );


                row.querySelector(
                    '[data-field="radar"]'
                )
                    ?.addEventListener(
                        "change",
                        event => {

                            const current =
                                item();


                            if (!current) {

                                return;

                            }


                            if (
                                event.target.checked
                            ) {

                                const count =
                                    start11V12DevelopmentDraft
                                        .attributes
                                        .filter(
                                            attribute =>
                                                attribute.radar !==
                                                false
                                        )
                                        .length;


                                if (
                                    count >=
                                    8
                                ) {

                                    event.target.checked =
                                        false;


                                    if (
                                        typeof visNotification ===
                                        "function"
                                    ) {

                                        visNotification(
                                            "Der kan maks. vises 8 attributes på radardiagrammet."
                                        );

                                    }


                                    return;

                                }

                            }


                            current.radar =
                                event.target.checked;


                            start11V12RenderSide();

                        }
                    );


                row.querySelector(
                    "[data-delete]"
                )
                    ?.addEventListener(
                        "click",
                        () => {

                            start11V12DevelopmentDraft.attributes =
                                start11V12DevelopmentDraft
                                    .attributes
                                    .filter(
                                        attribute =>
                                            attribute.id !==
                                            id
                                    );


                            start11V12RenderContent();

                            start11V12RenderTop();

                            start11V12RenderSide();

                        }
                    );

            }
        );


    document.getElementById(
        "s11v12AddAttr"
    )
        ?.addEventListener(
            "click",
            () => {

                const radarCount =
                    start11V12DevelopmentDraft
                        .attributes
                        .filter(
                            item =>
                                item.radar !==
                                false
                        )
                        .length;


                start11V12DevelopmentDraft
                    .attributes
                    .push({
                        id:
                            "attribute_" +
                            Date.now() +
                            "_" +
                            Math.random()
                                .toString(36)
                                .slice(2,6),

                        name:
                            "Nyt attribute",

                        category:
                            "Teknisk",

                        rating:
                            50,

                        radar:
                            radarCount <
                            8
                    });


                start11V12RenderContent();

                start11V12RenderSide();

            }
        );

}


/* =========================================================
   FOCUS / TRAINING / VIDEO / EVALUATIONS / NOTES
========================================================= */

function start11V12BindList(
    root,
    key,
    rowSelector
) {

    root.querySelectorAll(
        rowSelector
    )
        .forEach(
            row => {

                const id =
                    row.dataset.id;


                const getItem =
                    () =>
                        start11V12DevelopmentDraft[
                            key
                        ]
                            .find(
                                item =>
                                    item.id ===
                                    id
                            );


                row.querySelectorAll(
                    "[data-field]"
                )
                    .forEach(
                        field => {

                            field.addEventListener(
                                field.tagName ===
                                "SELECT"
                                    ? "change"
                                    : "input",
                                event => {

                                    const item =
                                        getItem();


                                    if (!item) {

                                        return;

                                    }


                                    item[
                                        field.dataset.field
                                    ] =
                                        event.target.value;


                                    start11V12RenderSide();

                                }
                            );

                        }
                    );


                row.querySelector(
                    "[data-delete]"
                )
                    ?.addEventListener(
                        "click",
                        () => {

                            start11V12DevelopmentDraft[
                                key
                            ] =
                                start11V12DevelopmentDraft[
                                    key
                                ]
                                    .filter(
                                        item =>
                                            item.id !==
                                            id
                                    );


                            start11V12RenderContent();

                            start11V12RenderSide();

                        }
                    );

            }
        );

}


