function start11V12RenderEvaluations(
    target
) {

    const items =
        [
            ...(
                start11V12DevelopmentDraft
                    .evaluations ||
                []
            )
        ]
            .sort(
                (
                    a,
                    b
                ) =>
                    String(
                        b.date ||
                        ""
                    )
                        .localeCompare(
                            String(
                                a.date ||
                                ""
                            )
                        )
            );


    target.innerHTML = `

        <section class="s11v12-panel">

            <div class="s11v12-panel-head">

                <div>
                    <strong>EVALUERINGSHISTORIK</strong>
                    <div class="s11v12-muted">
                        Gem et snapshot af de nuværende ratings.
                    </div>
                </div>

                <button
                    id="s11v12AddEvaluation"
                    class="s11v12-btn primary"
                >
                    + NY EVALUERING
                </button>

            </div>


            <div class="s11v12-stack">

                ${
                    items.length
                        ? items.map(
                            item => `
                                <div
                                    class="s11v12-item"
                                    data-eval-row
                                    data-id="${
                                        start11V12Escape(
                                            item.id
                                        )
                                    }"
                                >

                                    <div class="s11v12-row3">

                                        <div>
                                            <strong>
                                                ${
                                                    start11V12Escape(
                                                        item.title ||
                                                        "Evaluering"
                                                    )
                                                }
                                            </strong>

                                            <div class="s11v12-muted">
                                                ${
                                                    start11V12Escape(
                                                        item.date ||
                                                        ""
                                                    )
                                                }
                                                · OVR ${
                                                    typeof start11V11Overall ===
                                                        "function"
                                                        ? start11V11Overall({
                                                            attributes:
                                                                item.attributes ||
                                                                []
                                                        })
                                                        : ""
                                                }
                                            </div>
                                        </div>

                                        <div class="s11v12-muted">
                                            ${
                                                start11V12Escape(
                                                    item.note ||
                                                    "Ingen note."
                                                )
                                            }
                                        </div>

                                        <button
                                            class="s11v12-del"
                                            data-delete
                                        >
                                            ×
                                        </button>

                                    </div>

                                </div>
                            `
                        ).join("")
                        : `
                            <div class="s11v12-empty">
                                Ingen evalueringer endnu.
                            </div>
                        `
                }

            </div>

        </section>
    `;


    target.querySelectorAll(
        "[data-eval-row]"
    )
        .forEach(
            row => {

                row.querySelector(
                    "[data-delete]"
                )
                    ?.addEventListener(
                        "click",
                        () => {

                            start11V12DevelopmentDraft.evaluations =
                                start11V12DevelopmentDraft
                                    .evaluations
                                    .filter(
                                        item =>
                                            item.id !==
                                            row.dataset.id
                                    );


                            start11V12RenderContent();

                            start11V12RenderSide();

                        }
                    );

            }
        );


    document.getElementById(
        "s11v12AddEvaluation"
    )
        ?.addEventListener(
            "click",
            () => {

                const title =
                    window.prompt(
                        "Titel på evalueringen:",
                        "Status " +
                        new Date()
                            .toLocaleDateString(
                                "da-DK"
                            )
                    );


                if (
                    title === null
                ) {

                    return;

                }


                const note =
                    window.prompt(
                        "Kort note:",
                        ""
                    ) || "";


                start11V12DevelopmentDraft
                    .evaluations
                    .push({
                        id:
                            "evaluation_" +
                            Date.now(),

                        date:
                            new Date()
                                .toISOString()
                                .slice(
                                    0,
                                    10
                                ),

                        title:
                            title ||
                            "Evaluering",

                        note,

                        attributes:
                            start11V12Clone(
                                start11V12DevelopmentDraft
                                    .attributes
                            )
                    });


                start11V12RenderContent();

                start11V12RenderSide();

            }
        );

}


