function start11V12BuildStandalonePdf() {

    const player =
        start11V12ProfileDraft;

    const development =
        start11V12DevelopmentDraft;


    const meta =
        typeof start11V8GetActiveMeta ===
            "function"
            ? start11V8GetActiveMeta()
            : {
                clubName:
                    "START11",
                teamName:
                    ""
            };


    const theme =
        typeof start11V9GetActiveTheme ===
            "function"
            ? start11V9GetActiveTheme()
            : {};


    const primary =
        theme.primaryColor ||
        "#65D13C";


    const logo =
        theme.logo ||
        "";


    const radar =
        start11V12Radar(
            development,
            390
        );


    const attrRows =
        (
            development.attributes ||
            []
        )
            .map(
                item => `
                    <tr>
                        <td>
                            ${
                                start11V12Escape(
                                    item.name
                                )
                            }
                        </td>

                        <td>
                            ${
                                start11V12Escape(
                                    item.category
                                )
                            }
                        </td>

                        <td>
                            <strong>
                                ${
                                    Number(
                                        item.rating ||
                                        0
                                    )
                                }
                            </strong>
                        </td>
                    </tr>
                `
            )
            .join(
                ""
            );


    const focus =
        (
            development.focus ||
            []
        )
            .map(
                item => `
                    <div class="card">
                        <h3>
                            ${
                                start11V12Escape(
                                    item.title ||
                                    "Fokus"
                                )
                            }
                        </h3>

                        <p>
                            ${
                                start11V12Escape(
                                    item.description ||
                                    ""
                                )
                            }
                        </p>

                        ${
                            item.target
                                ? `
                                    <p>
                                        <strong>Mål:</strong>
                                        ${
                                            start11V12Escape(
                                                item.target
                                            )
                                        }
                                    </p>
                                `
                                : ""
                        }
                    </div>
                `
            )
            .join(
                ""
            ) ||
        `
            <div class="card">
                Ingen udviklingsfokus registreret.
            </div>
        `;


    const trainingRows =
        (
            development.trainingPlan ||
            []
        )
            .map(
                item => `
                    <tr>
                        <td>
                            ${
                                start11V12Escape(
                                    item.exercise ||
                                    ""
                                )
                            }
                        </td>

                        <td>
                            ${
                                start11V12Escape(
                                    item.frequency ||
                                    ""
                                )
                            }
                        </td>

                        <td>
                            ${
                                start11V12Escape(
                                    item.goal ||
                                    ""
                                )
                            }
                        </td>

                        <td>
                            ${
                                start11V12Escape(
                                    item.status ||
                                    ""
                                )
                            }
                        </td>
                    </tr>
                `
            )
            .join(
                ""
            ) ||
        `
            <tr>
                <td colspan="4">
                    Ingen træningsplan registreret.
                </td>
            </tr>
        `;


    const videos =
        (
            development.videos ||
            []
        )
            .map(
                item => `
                    <div class="video">

                        <strong>
                            ${
                                start11V12Escape(
                                    item.title ||
                                    "Videoklip"
                                )
                            }
                        </strong>

                        <div class="muted">
                            ${
                                start11V12Escape(
                                    item.match ||
                                    ""
                                )
                            }

                            ${
                                item.timestamp
                                    ? ` · ${start11V12Escape(
                                        item.timestamp
                                    )}`
                                    : ""
                            }
                        </div>

                        ${
                            item.note
                                ? `
                                    <p>
                                        ${
                                            start11V12Escape(
                                                item.note
                                            )
                                        }
                                    </p>
                                `
                                : ""
                        }

                        ${
                            item.url
                                ? `
                                    <a
                                        href="${
                                            start11V12Escape(
                                                item.url
                                            )
                                        }"
                                    >
                                        ${
                                            start11V12Escape(
                                                item.url
                                            )
                                        }
                                    </a>
                                `
                                : ""
                        }

                    </div>
                `
            )
            .join(
                ""
            ) ||
        `
            <p>
                Ingen videoklip registreret.
            </p>
        `;


    return `
<!DOCTYPE html>

<html lang="da">

<head>

    <meta charset="UTF-8">

    <title>
        ${
            start11V12Escape(
                player.name
            )
        } - Individuel spillerudvikling
    </title>

    <style>

        * {
            box-sizing: border-box;
        }

        body {
            margin: 0;
            background: #fff;
            color: #111;
            font-family:
                Arial,
                Helvetica,
                sans-serif;
        }

        .page {
            width: 210mm;
            min-height: 297mm;
            margin: 0 auto;
            padding: 14mm;
            page-break-after: always;
        }

        .page:last-child {
            page-break-after: auto;
        }

        header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            gap: 20px;

            padding-bottom: 7mm;

            border-bottom:
                3px solid
                ${primary};
        }

        .brand {
            color: ${primary};
            font-size: 12px;
            font-weight: 900;
            letter-spacing: 1.5px;
        }

        h1 {
            margin: 2mm 0 1mm;
            font-size: 25px;
        }

        h2 {
            margin:
                0 0 4mm;
            font-size: 14px;
        }

        h3 {
            margin:
                0 0 2mm;
            font-size: 11px;
        }

        p,
        td,
        th {
            font-size: 9.5px;
            line-height: 1.45;
        }

        .meta {
            color: #666;
            font-size: 9px;
        }

        .logo {
            width: 23mm;
            height: 23mm;
            object-fit: contain;
        }

        .grid {
            display: grid;
            grid-template-columns:
                1fr
                1fr;

            gap: 7mm;

            margin-top: 8mm;
        }

        .card {
            padding: 5mm;

            border:
                1px solid
                #DDD;

            border-radius: 3mm;
        }

        .rating {
            color: ${primary};
            font-size: 28px;
            font-weight: 900;
        }

        table {
            width: 100%;
            border-collapse: collapse;
        }

        th,
        td {
            padding: 2.5mm;
            border-bottom:
                1px solid
                #DDD;
            text-align: left;
            vertical-align: top;
        }

        th {
            color: #555;
            font-size: 8px;
            text-transform: uppercase;
        }

        .video {
            padding: 4mm 0;
            border-bottom:
                1px solid
                #DDD;
        }

        .video a {
            color: #111;
            word-break: break-all;
        }

        .muted {
            margin-top: 1mm;
            color: #666;
            font-size: 8px;
        }

        .radar svg {
            width: 100%;
            height: auto;
        }

        .radar text {
            fill: #111 !important;
        }

        .radar polygon {
            stroke: #999;
        }

        @page {
            size: A4 portrait;
            margin: 0;
        }

        @media print {

            .page {
                margin: 0;
            }

        }

    </style>

</head>


<body>

    <section class="page">

        <header>

            <div>

                <div class="brand">
                    START11 · ${
                        start11V12Escape(
                            meta.clubName ||
                            ""
                        )
                    }
                </div>

                <h1>
                    Individuel spillerudvikling
                </h1>

                <div class="meta">
                    ${
                        start11V12Escape(
                            player.name
                        )
                    }
                    · #${
                        start11V12Escape(
                            player.number ||
                            "—"
                        )
                    }
                    · ${
                        start11V12Escape(
                            player.position ||
                            "—"
                        )
                    }
                    · ${
                        start11V12Escape(
                            meta.teamName ||
                            ""
                        )
                    }
                </div>

            </div>

            ${
                logo
                    ? `
                        <img
                            class="logo"
                            src="${
                                start11V12Escape(
                                    logo
                                )
                            }"
                        >
                    `
                    : ""
            }

        </header>


        <div class="grid">

            <div class="card">

                <h2>Spillerprofil</h2>

                <div class="rating">
                    ${start11V12Overall()}
                </div>

                <p>
                    <strong>Position:</strong>
                    ${
                        start11V12Escape(
                            player.position ||
                            "—"
                        )
                    }
                </p>

                <p>
                    <strong>Styrker:</strong><br>
                    ${
                        start11V12Escape(
                            player.strengths ||
                            "Ikke udfyldt."
                        )
                    }
                </p>

                <p>
                    <strong>Udviklingsområder:</strong><br>
                    ${
                        start11V12Escape(
                            player.weaknesses ||
                            "Ikke udfyldt."
                        )
                    }
                </p>

                <p>
                    <strong>Trænerens vurdering:</strong><br>
                    ${
                        start11V12Escape(
                            development.coachNote ||
                            "Ikke udfyldt."
                        )
                    }
                </p>

            </div>


            <div class="card radar">

                <h2>Radardiagram</h2>

                ${radar}

            </div>

        </div>


        <div
            class="card"
            style="margin-top:7mm;"
        >

            <h2>Attributes</h2>

            <table>

                <thead>
                    <tr>
                        <th>Attribute</th>
                        <th>Kategori</th>
                        <th>Rating</th>
                    </tr>
                </thead>

                <tbody>
                    ${attrRows}
                </tbody>

            </table>

        </div>

    </section>


    <section class="page">

        <header>

            <div>

                <div class="brand">
                    START11 · ${
                        start11V12Escape(
                            meta.clubName ||
                            ""
                        )
                    }
                </div>

                <h1>
                    Fokus & træningsplan
                </h1>

                <div class="meta">
                    ${
                        start11V12Escape(
                            player.name
                        )
                    }
                </div>

            </div>

            ${
                logo
                    ? `
                        <img
                            class="logo"
                            src="${
                                start11V12Escape(
                                    logo
                                )
                            }"
                        >
                    `
                    : ""
            }

        </header>


        <h2
            style="margin-top:8mm;"
        >
            Spillerfokus
        </h2>

        <div class="grid">
            ${focus}
        </div>


        <div
            class="card"
            style="margin-top:8mm;"
        >

            <h2>
                Individuel træningsplan
            </h2>

            <table>

                <thead>
                    <tr>
                        <th>Øvelse</th>
                        <th>Hyppighed</th>
                        <th>Mål</th>
                        <th>Status</th>
                    </tr>
                </thead>

                <tbody>
                    ${trainingRows}
                </tbody>

            </table>

        </div>

    </section>


    <section class="page">

        <header>

            <div>

                <div class="brand">
                    START11 · ${
                        start11V12Escape(
                            meta.clubName ||
                            ""
                        )
                    }
                </div>

                <h1>
                    Video & noter
                </h1>

                <div class="meta">
                    ${
                        start11V12Escape(
                            player.name
                        )
                    }
                </div>

            </div>

            ${
                logo
                    ? `
                        <img
                            class="logo"
                            src="${
                                start11V12Escape(
                                    logo
                                )
                            }"
                        >
                    `
                    : ""
            }

        </header>


        <div
            class="card"
            style="margin-top:8mm;"
        >

            <h2>Videoklip</h2>

            ${videos}

        </div>


        <div
            class="card"
            style="margin-top:8mm;"
        >

            <h2>Med bold</h2>

            <p>
                ${
                    start11V12Escape(
                        player.focusWithBall ||
                        "Ikke udfyldt."
                    )
                }
            </p>


            <h2>Uden bold</h2>

            <p>
                ${
                    start11V12Escape(
                        player.focusWithoutBall ||
                        "Ikke udfyldt."
                    )
                }
            </p>

        </div>

    </section>

</body>

</html>
    `;

}


function start11V12GeneratePdf() {

    if (
        !start11V12Save(
            false
        )
    ) {

        return;

    }


    /*
        Åbn vinduet direkte i klik-eventet.
        Det er mere robust end V11's window.print() på hovedsiden
        og undgår at eksisterende app-CSS skjuler PDF'en.
    */
    const printWindow =
        window.open(
            "",
            "_blank",
            "width=1000,height=800"
        );


    if (!printWindow) {

        if (
            typeof visNotification ===
            "function"
        ) {

            visNotification(
                "Browseren blokerede PDF-vinduet. Tillad popups for START11 og prøv igen."
            );

        }


        return;

    }


    printWindow.document.open();

    printWindow.document.write(
        start11V12BuildStandalonePdf()
    );

    printWindow.document.close();


    printWindow.focus();


    setTimeout(
        () => {

            printWindow.print();

        },
        700
    );

}


