/* =========================================================
   KALENDER – DIREKTE ADGANG
========================================================= */

function s15InstallCalendarNav() {

    if (
        document.getElementById(
            "s15CalendarNav"
        )
    ) {
        return;
    }

    const nav =
        document.querySelector(
            ".start11-main-nav"
        );

    if (!nav) {
        return;
    }

    const button =
        document.createElement(
            "button"
        );

    button.id =
        "s15CalendarNav";

    button.type =
        "button";

    button.className =
        "start11-nav-item";

    button.textContent =
        "KALENDER";

    button.addEventListener(
        "click",
        () => {

            document
                .querySelectorAll(
                    ".start11-nav-item"
                )
                .forEach(
                    item =>
                        item.classList.remove(
                            "active"
                        )
                );

            button.classList.add(
                "active"
            );

            const section =
                document.getElementById(
                    "matchesSection"
                );

            section?.scrollIntoView({
                behavior:
                    "smooth",
                block:
                    "start"
            });

            setTimeout(
                () => {

                    if (
                        typeof start11CalendarSetOpen ===
                        "function"
                    ) {

                        start11CalendarSetOpen(
                            true
                        );

                    }

                },
                220
            );

        }
    );

    const coaching =
        document.getElementById(
            "s13nav"
        );

    if (coaching) {

        nav.insertBefore(
            button,
            coaching
        );

    } else {

        nav.appendChild(
            button
        );

    }

}


/* =========================================================
   KALENDER – TRÆNINGER
========================================================= */

function s15TrainingSessionsForDate(
    date
) {

    s15EnsureData();

    return s13Data.sessions.filter(
        session =>
            session.date ===
            date
    );

}


function s15CreateTrainingFromCalendar(
    date
) {

    s15EnsureData();

    const session = {
        id:
            s13Id(
                "session"
            ),

        date:
            date ||
            s13Today(),

        title:
            "Træning",

        theme:
            "",

        note:
            "",

        blocks:
            [],

        attendance:
            {},

        attachments:
            []
    };

    s13Data.sessions.push(
        session
    );

    s13Session =
        session.id;

    s13AttendanceSession =
        session.id;

    s13Save();

    if (
        typeof start11CalendarSetOpen ===
        "function"
    ) {

        start11CalendarSetOpen(
            false
        );

    }

    if (
        typeof s13Open ===
        "function"
    ) {

        s13Open();

        s13Tab =
            "training";

        s13Render();

        setTimeout(
            () => {

                if (
                    typeof s13EditSession ===
                    "function"
                ) {

                    s13EditSession();

                }

            },
            40
        );

    }

}


function s15EnsureCalendarTrainingButton() {

    const toolbar =
        document.querySelector(
            "#start11CalendarShell .start11-calendar-nav:last-child"
        );

    if (
        !toolbar ||
        document.getElementById(
            "s15CalendarAddTraining"
        )
    ) {
        return;
    }

    const button =
        document.createElement(
            "button"
        );

    button.id =
        "s15CalendarAddTraining";

    button.type =
        "button";

    button.className =
        "start11-calendar-action s15-calendar-add-training";

    button.textContent =
        "+ TRÆNING";

    const friendly =
        document.getElementById(
            "start11CalendarAddFriendly"
        );

    if (friendly) {

        toolbar.insertBefore(
            button,
            friendly
        );

    } else {

        toolbar.appendChild(
            button
        );

    }

    button.addEventListener(
        "click",
        () => {

            const date =
                window.prompt(
                    "Dato for træningen (ÅÅÅÅ-MM-DD):",
                    s13Today()
                );

            if (
                !date
            ) {
                return;
            }

            s15CreateTrainingFromCalendar(
                date
            );

        }
    );

}


function s15CalendarDayDates() {

    if (
        typeof start11CalendarDate ===
        "undefined"
    ) {
        return [];
    }

    const year =
        start11CalendarDate.getFullYear();

    const month =
        start11CalendarDate.getMonth();

    const first =
        new Date(
            year,
            month,
            1
        );

    const mondayIndex =
        (
            first.getDay() +
            6
        ) %
        7;

    const start =
        new Date(
            year,
            month,
            1 -
            mondayIndex
        );

    const dates = [];

    for (
        let i =
            0;
        i <
            42;
        i++
    ) {

        const date =
            new Date(
                start.getFullYear(),
                start.getMonth(),
                start.getDate() +
                i
            );

        dates.push(
            `${date.getFullYear()}-${String(
                date.getMonth() +
                1
            ).padStart(
                2,
                "0"
            )}-${String(
                date.getDate()
            ).padStart(
                2,
                "0"
            )}`
        );

    }

    return dates;

}


function s15DecorateCalendarTrainings() {

    s15EnsureData();

    s15EnsureCalendarTrainingButton();

    const grid =
        document.getElementById(
            "start11CalendarGrid"
        );

    if (!grid) {
        return;
    }

    const days =
        [
            ...grid.querySelectorAll(
                ".start11-calendar-day"
            )
        ];

    const dates =
        s15CalendarDayDates();

    days.forEach(
        (
            day,
            index
        ) => {

            const date =
                dates[
                    index
                ];

            if (!date) {
                return;
            }

            day.dataset.s15Date =
                date;

            day.querySelectorAll(
                ".s15-calendar-training"
            )
                .forEach(
                    item =>
                        item.remove()
                );

            s15TrainingSessionsForDate(
                date
            )
                .forEach(
                    session => {

                        const button =
                            document.createElement(
                                "button"
                            );

                        button.type =
                            "button";

                        button.className =
                            "s15-calendar-training";

                        button.textContent =
                            "TRÆNING · " +
                            (
                                session.theme ||
                                session.title ||
                                "Træning"
                            );

                        button.addEventListener(
                            "click",
                            event => {

                                event.stopPropagation();

                                if (
                                    typeof start11CalendarSetOpen ===
                                    "function"
                                ) {

                                    start11CalendarSetOpen(
                                        false
                                    );

                                }

                                s13Session =
                                    session.id;

                                if (
                                    typeof s13Open ===
                                    "function"
                                ) {

                                    s13Open();

                                    s13Tab =
                                        "training";

                                    s13Render();

                                    setTimeout(
                                        () =>
                                            s13EditSession?.(),
                                        30
                                    );

                                }

                            }
                        );

                        day.appendChild(
                            button
                        );

                    }
                );

            if (
                day.dataset.s15ClickBound !==
                "1"
            ) {

                day.dataset.s15ClickBound =
                    "1";

                day.addEventListener(
                    "dblclick",
                    event => {

                        if (
                            event.target.closest(
                                "button"
                            )
                        ) {
                            return;
                        }

                        const selectedDate =
                            day.dataset
                                .s15Date;

                        if (
                            !selectedDate
                        ) {
                            return;
                        }

                        s15CreateTrainingFromCalendar(
                            selectedDate
                        );

                    }
                );

                day.title =
                    "Dobbeltklik på dagen for at oprette træning";

            }

        }
    );

    s15RenderCalendarTrainingList();

}


function s15RenderCalendarTrainingList() {

    const shell =
        document.getElementById(
            "start11CalendarShell"
        );

    if (
        !shell ||
        typeof start11CalendarDate ===
            "undefined"
    ) {
        return;
    }

    shell.querySelector(
        ".s15-calendar-month-trainings"
    )
        ?.remove();

    const year =
        start11CalendarDate.getFullYear();

    const month =
        start11CalendarDate.getMonth();

    const sessions =
        s13Data.sessions
            .filter(
                session => {

                    if (
                        !session.date
                    ) {
                        return false;
                    }

                    const date =
                        new Date(
                            session.date +
                            "T12:00:00"
                        );

                    return (
                        !Number.isNaN(
                            date.getTime()
                        ) &&
                        date.getFullYear() ===
                            year &&
                        date.getMonth() ===
                            month
                    );

                }
            )
            .sort(
                (
                    a,
                    b
                ) =>
                    String(
                        a.date
                    )
                        .localeCompare(
                            String(
                                b.date
                            )
                        )
            );

    const section =
        document.createElement(
            "div"
        );

    section.className =
        "s15-calendar-month-trainings";

    section.innerHTML = `
        <div class="start11-calendar-month-list-title">
            Månedens træninger
        </div>

        ${
            sessions.length
                ? sessions
                    .map(
                        session => `
                            <div
                                class="s15-calendar-training-row"
                                data-s15-session="${
                                    s13Esc(
                                        session.id
                                    )
                                }"
                            >
                                <div>
                                    ${
                                        s13Date(
                                            session.date
                                        )
                                    }
                                </div>

                                <div>
                                    <strong>
                                        ${
                                            s13Esc(
                                                session.title ||
                                                "Træning"
                                            )
                                        }
                                    </strong>

                                    <div class="s13mut">
                                        ${
                                            s13Esc(
                                                session.theme ||
                                                "Intet tema"
                                            )
                                        }
                                        ·
                                        ${
                                            (
                                                session.blocks ||
                                                []
                                            )
                                                .reduce(
                                                    (
                                                        total,
                                                        block
                                                    ) =>
                                                        total +
                                                        Number(
                                                            block.duration ||
                                                            0
                                                        ),
                                                    0
                                                )
                                        } min
                                    </div>
                                </div>

                                <button
                                    type="button"
                                    class="s13btn"
                                    data-open
                                >
                                    ÅBN
                                </button>
                            </div>
                        `
                    )
                    .join(
                        ""
                    )
                : `
                    <div class="start11-calendar-empty">
                        Ingen træninger i denne måned.
                    </div>
                `
        }
    `;

    shell.appendChild(
        section
    );

    section.querySelectorAll(
        "[data-s15-session]"
    )
        .forEach(
            row => {

                row.querySelector(
                    "[data-open]"
                )
                    ?.addEventListener(
                        "click",
                        () => {

                            const id =
                                row.dataset
                                    .s15Session;

                            start11CalendarSetOpen?.(
                                false
                            );

                            s13Session =
                                id;

                            s13Open?.();

                            s13Tab =
                                "training";

                            s13Render?.();

                            setTimeout(
                                () =>
                                    s13EditSession?.(),
                                30
                            );

                        }
                    );

            }
        );

}


/*
    Træninger skal med hver gang kalenderen renderes.
*/
if (
    typeof start11RenderCalendarV3 ===
    "function"
) {

    const s15RenderCalendarBefore =
        start11RenderCalendarV3;

    start11RenderCalendarV3 =
        function (
            ...args
        ) {

            const result =
                s15RenderCalendarBefore(
                    ...args
                );

            setTimeout(
                s15DecorateCalendarTrainings,
                0
            );

            return result;

        };

}


