/* =========================================================
   DYNAMISK INIT
========================================================= */

function s15RefreshDynamic() {

    s15EnsureData();

    s15InstallCalendarNav();

    s15EnsureCalendarTrainingButton();

    s15DecorateCalendarTrainings();

    s15WatchSessionEditor();

}


function s15Init() {

    s15EnsureData();

    s15InstallStyles();

    s15InstallCalendarNav();

    s15EnsureCalendarTrainingButton();

    s15DecorateCalendarTrainings();

    s15WatchSessionEditor();


    let timer =
        null;

    const observer =
        new MutationObserver(
            mutations => {

                const relevant =
                    mutations.some(
                        mutation =>
                            [
                                ...mutation.addedNodes
                            ]
                                .some(
                                    node => {

                                        if (
                                            !(
                                                node instanceof
                                                Element
                                            )
                                        ) {
                                            return false;
                                        }

                                        return (
                                            node.id ===
                                                "start11CalendarShell" ||
                                            node.id ===
                                                "start11CalendarGrid" ||
                                            node.id ===
                                                "s13sessionedit" ||
                                            node.querySelector?.(
                                                "#start11CalendarShell,#start11CalendarGrid,#s13sessionedit"
                                            )
                                        );

                                    }
                                )
                    );

                if (!relevant) {
                    return;
                }

                if (timer) {
                    clearTimeout(
                        timer
                    );
                }

                timer =
                    setTimeout(
                        () => {

                            timer =
                                null;

                            s15RefreshDynamic();

                        },
                        90
                    );

            }
        );

    observer.observe(
        document.body,
        {
            childList:
                true,
            subtree:
                true
        }
    );

}


if (
    document.readyState ===
    "loading"
) {

    document.addEventListener(
        "DOMContentLoaded",
        () =>
            setTimeout(
                s15Init,
                2350
            )
    );

} else {

    setTimeout(
        s15Init,
        2350
    );

}



