/* =========================================================
   DATA – GAMMEL KAMPPLAN PR. KAMP
========================================================= */

function s16EnsureData() {

    if (
        !s13Data ||
        typeof s13Data !== "object"
    ) {
        s13Data = {};
    }

    if (
        !Array.isArray(
            s13Data.legacyMatchPlans
        )
    ) {
        s13Data.legacyMatchPlans = [];
    }

}


if (
    typeof s13Norm ===
    "function"
) {

    const s16NormBefore =
        s13Norm;

    s13Norm =
        function (
            raw = {}
        ) {

            const data =
                s16NormBefore(
                    raw
                );

            data.legacyMatchPlans =
                Array.isArray(
                    raw.legacyMatchPlans
                )
                    ? raw.legacyMatchPlans
                    : [];

            return data;

        };

}


