function s16BindOldMatchPlanSave() {

    const button =
        document.getElementById(
            "saveMatchplan"
        );

    if (
        !button ||
        button.dataset.s16PerMatchBound ===
            "1"
    ) {
        return;
    }

    button.dataset.s16PerMatchBound =
        "1";

    button.addEventListener(
        "click",
        () => {

            setTimeout(
                () => {

                    s16SaveCurrentLegacyMatchPlan();

                },
                0
            );

        }
    );

}


