function s16EnsureCalendarModal() {

    let modal =
        document.getElementById(
            "s16CalendarModal"
        );

    if (modal) {
        return modal;
    }

    modal =
        document.createElement(
            "div"
        );

    modal.id =
        "s16CalendarModal";

    modal.className =
        "modal";

    modal.innerHTML = `

        <div
            class="
                modal-content
                s16-calendar-shell
            "
        >

            <header class="s16-calendar-top">

                <div>
                    <h2>KALENDER</h2>

                    <p id="s16CalendarSubtitle">
                        Kampe, træninger og træningskampe
                    </p>
                </div>

                <button
                    type="button"
                    class="s13btn"
                    id="s16CalendarClose"
                >
                    LUK
                </button>

            </header>

            <div
                id="s16CalendarBody"
                class="s16-calendar-body"
            ></div>

        </div>
    `;

    document.body.appendChild(
        modal
    );

    modal.addEventListener(
        "mousedown",
        event => {

            if (
                event.target ===
                modal
            ) {

                start11CalendarSetOpen?.(
                    false
                );

            }

        }
    );

    document.getElementById(
        "s16CalendarClose"
    )
        ?.addEventListener(
            "click",
            () =>
                start11CalendarSetOpen?.(
                    false
                )
        );

    return modal;

}


function s16MoveCalendarIntoModal() {

    const modal =
        s16EnsureCalendarModal();

    const body =
        document.getElementById(
            "s16CalendarBody"
        );

    const calendar =
        document.getElementById(
            "start11CalendarShell"
        );

    if (
        !modal ||
        !body ||
        !calendar
    ) {
        return false;
    }

    if (
        calendar.parentElement !==
        body
    ) {

        body.appendChild(
            calendar
        );

    }

    return true;

}


/* =========================================================
   OVERRIDE: ÅBN/LUK KALENDER
========================================================= */

start11CalendarSetOpen =
    function (
        open
    ) {

        const modal =
            s16EnsureCalendarModal();

        /*
            Kalenderens HTML oprettes af det eksisterende system.
            Flyt det blot ind i modal-vinduet.
        */
        s16MoveCalendarIntoModal();

        const calendar =
            document.getElementById(
                "start11CalendarShell"
            );

        if (
            !modal ||
            !calendar
        ) {
            return;
        }

        const section =
            document.getElementById(
                "matchesSection"
            );

        /*
            Fjern gammel inline-dashboard calendar mode.
        */
        section?.classList.remove(
            "start11-calendar-mode"
        );

        if (
            open
        ) {

            /*
                Åbn automatisk på måneden med nærmeste kommende kamp,
                ligesom før.
            */
            try {

                const next =
                    start11CalendarV3SortedMatches()
                        .find(
                            start11CalendarV3IsUpcoming
                        );

                if (next) {

                    const date =
                        start11CalendarDateObject(
                            next
                        );

                    if (date) {

                        start11CalendarDate =
                            new Date(
                                date.getFullYear(),
                                date.getMonth(),
                                1
                            );

                    }

                }

            } catch {

            }

            calendar.classList.add(
                "active"
            );

            modal.style.display =
                "flex";

            const meta =
                typeof s13Meta ===
                    "function"
                    ? s13Meta()
                    : {};

            const subtitle =
                document.getElementById(
                    "s16CalendarSubtitle"
                );

            if (subtitle) {

                subtitle.textContent =
                    [
                        meta.clubName ||
                            "",
                        meta.teamName ||
                            "",
                        "kampe, træninger og træningskampe"
                    ]
                        .filter(
                            Boolean
                        )
                        .join(
                            " · "
                        );

            }

            if (
                typeof start11RenderCalendar ===
                    "function"
            ) {

                start11RenderCalendar();

            }

            setTimeout(
                () => {

                    s15DecorateCalendarTrainings?.();

                },
                0
            );

        } else {

            modal.style.display =
                "none";

        }

    };


/* =========================================================
   TOPMENU KALENDER – ÅBN KUN MODAL
========================================================= */

function s16RebindCalendarNav() {

    const old =
        document.getElementById(
            "s15CalendarNav"
        );

    if (!old) {
        return;
    }

    /*
        Klon knappen for at fjerne V15's gamle scroll-handler.
    */
    const button =
        old.cloneNode(
            true
        );

    old.replaceWith(
        button
    );

    button.addEventListener(
        "click",
        () => {

            start11CalendarSetOpen(
                true
            );

        }
    );

}


/* =========================================================
   KALENDERENS HEADERKNAP
========================================================= */

function s16RebindCalendarHeaderButton() {

    const old =
        document.getElementById(
            "start11CalendarHeaderButton"
        );

    if (
        !old ||
        old.dataset.s16CalendarBound ===
            "1"
    ) {
        return;
    }

    /*
        Her behøver vi ikke klone: den gamle handler kalder også
        start11CalendarSetOpen(true), som nu er vores modal-version.
    */
    old.dataset.s16CalendarBound =
        "1";

}


/* =========================================================
   CLEANUP AF V14 GAMEPLAN UI
========================================================= */

function s16RemoveNewGamePlanUi() {

    document.getElementById(
        "s14GamePlanModal"
    )
        ?.remove();

    document.querySelectorAll(
        ".s14-upcoming-plan-badge"
    )
        .forEach(
            item =>
                item.remove()
        );

}


/* =========================================================
   DYNAMISK REFRESH
========================================================= */

function s16RefreshDynamic() {

    s16EnsureData();

    s16BindOldMatchPlanSave();

    s16MoveCalendarIntoModal();

    s16RebindCalendarHeaderButton();

    s16RemoveNewGamePlanUi();

}


/* =========================================================
   INIT
========================================================= */

function s16Init() {

    s16EnsureData();

    s16InstallStyles();

    s16EnsureCalendarModal();

    s16RemoveNewGamePlanUi();

    /*
        V15 opretter KALENDER-knappen lidt tidligere.
        Bind den om efter alle tidligere init-funktioner er kørt.
    */
    s16RebindCalendarNav();

    s16RefreshDynamic();


    let timer =
        null;

    const observer =
        new MutationObserver(
            mutations => {

                const relevant =
                    mutations.some(
                        mutation =>
                            [
                                ...mutation.addedNodes
                            ]
                                .some(
                                    node => {

                                        if (
                                            !(
                                                node instanceof
                                                Element
                                            )
                                        ) {
                                            return false;
                                        }

                                        return (
                                            node.id ===
                                                "start11CalendarShell" ||
                                            node.id ===
                                                "s15CalendarNav" ||
                                            node.id ===
                                                "s14GamePlanModal" ||
                                            node.id ===
                                                "saveMatchplan" ||
                                            node.querySelector?.(
                                                "#start11CalendarShell,#s15CalendarNav,#s14GamePlanModal,#saveMatchplan"
                                            )
                                        );

                                    }
                                )
                    );

                if (!relevant) {
                    return;
                }

                if (timer) {
                    clearTimeout(
                        timer
                    );
                }

                timer =
                    setTimeout(
                        () => {

                            timer =
                                null;

                            /*
                                Hvis V15 har genoprettet kalenderknappen,
                                bind den om.
                            */
                            const nav =
                                document.getElementById(
                                    "s15CalendarNav"
                                );

                            if (
                                nav &&
                                nav.dataset.s16Rebound !==
                                    "1"
                            ) {

                                s16RebindCalendarNav();

                                const rebound =
                                    document.getElementById(
                                        "s15CalendarNav"
                                    );

                                if (rebound) {

                                    rebound.dataset.s16Rebound =
                                        "1";

                                }

                            }

                            s16RefreshDynamic();

                        },
                        100
                    );

            }
        );

    observer.observe(
        document.body,
        {
            childList:
                true,
            subtree:
                true
        }
    );

}


if (
    document.readyState ===
    "loading"
) {

    document.addEventListener(
        "DOMContentLoaded",
        () =>
            setTimeout(
                s16Init,
                2700
            )
    );

} else {

    setTimeout(
        s16Init,
        2700
    );

}



