/* =========================================================
   DATA
========================================================= */

function s17EnsureExerciseData() {

    if (
        !s13Data ||
        typeof s13Data !== "object"
    ) {
        return;
    }

    if (
        !Array.isArray(
            s13Data.exercises
        )
    ) {
        s13Data.exercises = [];
    }

    s13Data.exercises.forEach(
        exercise => {

            if (
                typeof exercise.description !==
                "string"
            ) {
                exercise.description =
                    "";
            }

            if (
                typeof exercise.focusPoint !==
                "string"
            ) {
                exercise.focusPoint =
                    "";
            }

            if (
                !Array.isArray(
                    exercise.attachments
                )
            ) {
                exercise.attachments =
                    [];
            }

        }
    );

}


if (
    typeof s13Norm ===
    "function"
) {

    const s17NormBefore =
        s13Norm;

    s13Norm =
        function (
            raw = {}
        ) {

            const data =
                s17NormBefore(
                    raw
                );

            if (
                !Array.isArray(
                    data.exercises
                )
            ) {
                data.exercises = [];
            }

            data.exercises.forEach(
                exercise => {

                    exercise.description =
                        String(
                            exercise.description ||
                            ""
                        );

                    exercise.focusPoint =
                        String(
                            exercise.focusPoint ||
                            ""
                        );

                    exercise.attachments =
                        Array.isArray(
                            exercise.attachments
                        )
                            ? exercise.attachments
                            : [];

                }
            );

            return data;

        };

}


