/* =========================================================
   START11 – V19
   ---------------------------------------------------------
   1) ADVANCED EXERCISE TACTICAL BOARD
      - Tegn øvelser direkte i øvelsesbanken
      - Spillere, kegler, bolde, mål, mannequiner
      - Pile, afleveringslinjer, driblelinjer, zoner, tekst
      - Drag & drop
      - Flere animationstrin / frames
      - Hurtigskabelon til 4v2-rondo
      - Diagrammer følger automatisk med i trænings-PDF

   2) MATCH-SPECIFIC START11
      - Hver kalenderkamp får sin egen startopstilling
      - Egen formation + bænk pr. kamp
      - Klik på AGF viser AGF-opstillingen
      - Klik på FCK viser FCK-opstillingen
      - Ændringer gemmes kun på den konkrete kamp
      - Holdets normale START11 bevares
      - Knap til eksisterende KAMPPLAN/PDF
      - Mulighed for at kopiere seneste kampopstilling
========================================================= */


/* =========================================================
   GENERELLE V19 HELPERS
========================================================= */

function s19Clone(value) {

    try {

        if (
            typeof structuredClone ===
            "function"
        ) {
            return structuredClone(
                value
            );
        }

    } catch {

    }

    return JSON.parse(
        JSON.stringify(
            value
        )
    );

}


function s19Uid(prefix) {

    if (
        typeof s13Id ===
        "function"
    ) {
        return s13Id(
            prefix
        );
    }

    return (
        prefix +
        "_" +
        Date.now() +
        "_" +
        Math.random()
            .toString(36)
            .slice(2,8)
    );

}


/* =========================================================
   V19 DATA
========================================================= */

function s19EnsureData() {

    if (
        !s13Data ||
        typeof s13Data !==
        "object"
    ) {
        s13Data = {};
    }

    if (
        !Array.isArray(
            s13Data.matchLineups
        )
    ) {
        s13Data.matchLineups = [];
    }

    if (
        !Array.isArray(
            s13Data.exercises
        )
    ) {
        s13Data.exercises = [];
    }

    s13Data.exercises.forEach(
        exercise => {

            if (
                !exercise.diagram ||
                typeof exercise.diagram !==
                "object"
            ) {

                exercise.diagram =
                    s19DefaultDiagram();

            } else {

                exercise.diagram =
                    s19NormalizeDiagram(
                        exercise.diagram
                    );

            }

        }
    );

}


if (
    typeof s13Norm ===
    "function"
) {

    const s19NormBefore =
        s13Norm;

    s13Norm =
        function (
            raw = {}
        ) {

            const data =
                s19NormBefore(
                    raw
                );

            data.matchLineups =
                Array.isArray(
                    raw.matchLineups
                )
                    ? raw.matchLineups
                    : (
                        Array.isArray(
                            data.matchLineups
                        )
                            ? data.matchLineups
                            : []
                    );

            if (
                !Array.isArray(
                    data.exercises
                )
            ) {
                data.exercises = [];
            }

            data.exercises.forEach(
                exercise => {

                    exercise.diagram =
                        s19NormalizeDiagram(
                            exercise.diagram
                        );

                }
            );

            return data;

        };

}


/* =========================================================
   EXERCISE BOARD – DATA MODEL
========================================================= */

function s19EmptyFrame() {

    return {
        id:
            s19Uid(
                "diagram-frame"
            ),

        title:
            "Trin 1",

        duration:
            0,

        elements:
            [],

        arrows:
            [],

        zones:
            []
    };

}


function s19DefaultDiagram() {

    return {
        pitch:
            "plain",

        frames:
            [
                s19EmptyFrame()
            ],

        activeFrame:
            0
    };

}


function s19NormalizeDiagram(
    raw
) {

    if (
        !raw ||
        typeof raw !==
        "object"
    ) {
        return s19DefaultDiagram();
    }

    /*
        Migration fra et evt. ældre statisk diagram.
    */
    if (
        !Array.isArray(
            raw.frames
        )
    ) {

        const frame =
            s19EmptyFrame();

        frame.elements =
            Array.isArray(
                raw.elements
            )
                ? raw.elements
                : [];

        frame.arrows =
            Array.isArray(
                raw.arrows
            )
                ? raw.arrows
                : [];

        frame.zones =
            Array.isArray(
                raw.zones
            )
                ? raw.zones
                : [];

        raw = {
            pitch:
                raw.pitch ||
                "plain",

            frames:
                [
                    frame
                ],

            activeFrame:
                0
        };

    }

    if (
        !raw.frames.length
    ) {
        raw.frames.push(
            s19EmptyFrame()
        );
    }

    raw.frames.forEach(
        (
            frame,
            index
        ) => {

            frame.id =
                frame.id ||
                s19Uid(
                    "diagram-frame"
                );

            frame.title =
                frame.title ||
                `Trin ${index + 1}`;

            frame.duration =
                Number(
                    frame.duration ||
                    0
                );

            frame.elements =
                Array.isArray(
                    frame.elements
                )
                    ? frame.elements
                    : [];

            frame.arrows =
                Array.isArray(
                    frame.arrows
                )
                    ? frame.arrows
                    : [];

            frame.zones =
                Array.isArray(
                    frame.zones
                )
                    ? frame.zones
                    : [];

        }
    );

    raw.pitch =
        raw.pitch ||
        "plain";

    raw.activeFrame =
        Math.max(
            0,
            Math.min(
                raw.frames.length -
                1,
                Number(
                    raw.activeFrame ||
                    0
                )
            )
        );

    return raw;

}


function s19ExerciseForDesigner() {

    return s13Data.exercises.find(
        exercise =>
            exercise.id ===
            s13Exercise
    ) ||
    null;

}


function s19DiagramFrame(
    exercise
) {

    if (
        !exercise
    ) {
        return null;
    }

    exercise.diagram =
        s19NormalizeDiagram(
            exercise.diagram
        );

    return exercise.diagram.frames[
        exercise.diagram.activeFrame
    ] ||
    exercise.diagram.frames[0];
}


