/* =========================================================
   EXERCISE BOARD – POINTER EVENTS
========================================================= */

function s19BoardPoint(
    event,
    board
) {

    const rect =
        board.getBoundingClientRect();

    return {
        x:
            s19Clamp01(
                (
                    event.clientX -
                    rect.left
                ) /
                rect.width
            ),

        y:
            s19Clamp01(
                (
                    event.clientY -
                    rect.top
                ) /
                rect.height
            )
    };

}


function s19BindDiagramBoard(
    exercise
) {

    const board =
        document.getElementById(
            "s19DiagramBoard"
        );

    if (
        !board ||
        !exercise
    ) {
        return;
    }

    const frame =
        s19DiagramFrame(
            exercise
        );

    document.querySelectorAll(
        "[data-add-diagram]"
    )
        .forEach(
            button => {

                button.addEventListener(
                    "click",
                    () =>
                        s19AddDiagramElement(
                            exercise,
                            button.dataset
                                .addDiagram,
                            .5 +
                            (
                                Math.random() -
                                .5
                            ) *
                            .12,
                            .5 +
                            (
                                Math.random() -
                                .5
                            ) *
                            .12
                        )
                );

            }
        );

    document.querySelectorAll(
        "[data-diagram-tool]"
    )
        .forEach(
            button => {

                button.addEventListener(
                    "click",
                    () => {

                        s19DiagramState.tool =
                            button.dataset
                                .diagramTool;

                        s19RenderDiagramBoard(
                            exercise
                        );

                    }
                );

            }
        );

    document.getElementById(
        "s19DiagramColor"
    )
        ?.addEventListener(
            "input",
            event => {

                s19DiagramState.color =
                    event.target.value;

            }
        );

    document.getElementById(
        "s19PitchType"
    )
        ?.addEventListener(
            "change",
            event => {

                s19DiagramSnapshot(
                    exercise
                );

                exercise.diagram.pitch =
                    event.target.value;

                s13Save();

                s19RenderDiagramBoard(
                    exercise
                );

            }
        );

    document.getElementById(
        "s19RondoTemplate"
    )
        ?.addEventListener(
            "click",
            () =>
                s19Rondo4v2(
                    exercise
                )
        );

    document.getElementById(
        "s19DiagramUndo"
    )
        ?.addEventListener(
            "click",
            () =>
                s19DiagramUndo(
                    exercise
                )
        );

    document.getElementById(
        "s19DiagramRedo"
    )
        ?.addEventListener(
            "click",
            () =>
                s19DiagramRedo(
                    exercise
                )
        );

    document.getElementById(
        "s19DiagramDelete"
    )
        ?.addEventListener(
            "click",
            () =>
                s19DeleteSelectedDiagramItem(
                    exercise
                )
        );

    document.getElementById(
        "s19DiagramDuplicate"
    )
        ?.addEventListener(
            "click",
            () =>
                s19DuplicateSelectedDiagramItem(
                    exercise
                )
        );

    document.getElementById(
        "s19AddFrame"
    )
        ?.addEventListener(
            "click",
            () =>
                s19AddDiagramFrame(
                    exercise,
                    true
                )
        );

    document.getElementById(
        "s19DeleteFrame"
    )
        ?.addEventListener(
            "click",
            () =>
                s19DeleteDiagramFrame(
                    exercise
                )
        );

    document.querySelectorAll(
        "[data-diagram-frame]"
    )
        .forEach(
            button => {

                button.addEventListener(
                    "click",
                    () => {

                        exercise.diagram.activeFrame =
                            Number(
                                button.dataset
                                    .diagramFrame
                            );

                        s19DiagramState.selectedId =
                            null;

                        s13Save();

                        s19RenderDiagramBoard(
                            exercise
                        );

                    }
                );

            }
        );

    document.getElementById(
        "s19FrameTitle"
    )
        ?.addEventListener(
            "change",
            event => {

                frame.title =
                    event.target.value.trim() ||
                    `Trin ${exercise.diagram.activeFrame + 1}`;

                s13Save();

                s19RenderDiagramBoard(
                    exercise
                );

            }
        );

    document.getElementById(
        "s19FrameDuration"
    )
        ?.addEventListener(
            "change",
            event => {

                frame.duration =
                    Number(
                        event.target.value ||
                        0
                    );

                s13Save();

            }
        );


    /*
        DRAG ELEMENTS
    */
    board.querySelectorAll(
        "[data-diagram-element]"
    )
        .forEach(
            elementNode => {

                elementNode.addEventListener(
                    "pointerdown",
                    event => {

                        if (
                            s19DiagramState.tool !==
                            "select"
                        ) {
                            return;
                        }

                        event.stopPropagation();
                        event.preventDefault();

                        const id =
                            elementNode.dataset
                                .diagramElement;

                        const item =
                            frame.elements.find(
                                element =>
                                    element.id ===
                                    id
                            );

                        if (!item) {
                            return;
                        }

                        s19DiagramState.selectedId =
                            id;

                        s19DiagramSnapshot(
                            exercise
                        );

                        s19DiagramState.drag = {
                            id,
                            pointerId:
                                event.pointerId
                        };

                        elementNode.setPointerCapture?.(
                            event.pointerId
                        );

                        elementNode.classList.add(
                            "selected"
                        );

                    }
                );

                elementNode.addEventListener(
                    "pointermove",
                    event => {

                        if (
                            !s19DiagramState.drag ||
                            s19DiagramState.drag.id !==
                            elementNode.dataset
                                .diagramElement
                        ) {
                            return;
                        }

                        const point =
                            s19BoardPoint(
                                event,
                                board
                            );

                        const item =
                            frame.elements.find(
                                element =>
                                    element.id ===
                                    s19DiagramState.drag.id
                            );

                        if (!item) {
                            return;
                        }

                        item.x =
                            point.x;

                        item.y =
                            point.y;

                        elementNode.style.left =
                            point.x *
                            100 +
                            "%";

                        elementNode.style.top =
                            point.y *
                            100 +
                            "%";

                    }
                );

                elementNode.addEventListener(
                    "pointerup",
                    event => {

                        if (
                            !s19DiagramState.drag
                        ) {
                            return;
                        }

                        s19DiagramState.drag =
                            null;

                        s13Save();

                        s19RenderDiagramBoard(
                            exercise
                        );

                    }
                );

                elementNode.addEventListener(
                    "dblclick",
                    event => {

                        event.preventDefault();
                        event.stopPropagation();

                        const item =
                            frame.elements.find(
                                element =>
                                    element.id ===
                                    elementNode.dataset
                                        .diagramElement
                            );

                        if (!item) {
                            return;
                        }

                        if (
                            item.type.startsWith(
                                "player-"
                            ) ||
                            item.type ===
                            "text"
                        ) {

                            const label =
                                window.prompt(
                                    "Tekst / nummer:",
                                    item.label ||
                                    ""
                                );

                            if (
                                label !==
                                null
                            ) {

                                s19DiagramSnapshot(
                                    exercise
                                );

                                item.label =
                                    label.trim();

                                s13Save();

                                s19RenderDiagramBoard(
                                    exercise
                                );

                            }

                        }

                    }
                );

            }
        );


    /*
        TEGN PILE / ZONER
    */
    board.addEventListener(
        "pointerdown",
        event => {

            if (
                event.target.closest(
                    "[data-diagram-element]"
                )
            ) {
                return;
            }

            if (
                s19DiagramState.tool ===
                "select"
            ) {

                s19DiagramState.selectedId =
                    null;

                s19RenderDiagramBoard(
                    exercise
                );

                return;
            }

            const start =
                s19BoardPoint(
                    event,
                    board
                );

            s19DiagramState.draw = {
                start,
                end:
                    start
            };

            board.setPointerCapture?.(
                event.pointerId
            );

        }
    );

    board.addEventListener(
        "pointermove",
        event => {

            if (
                !s19DiagramState.draw
            ) {
                return;
            }

            s19DiagramState.draw.end =
                s19BoardPoint(
                    event,
                    board
                );

        }
    );

    board.addEventListener(
        "pointerup",
        event => {

            if (
                !s19DiagramState.draw
            ) {
                return;
            }

            const start =
                s19DiagramState.draw
                    .start;

            const end =
                s19BoardPoint(
                    event,
                    board
                );

            s19DiagramState.draw =
                null;

            s19DiagramSnapshot(
                exercise
            );

            if (
                s19DiagramState.tool ===
                "zone"
            ) {

                const zone = {
                    id:
                        s19Uid(
                            "diagram-zone"
                        ),

                    x1:
                        start.x,

                    y1:
                        start.y,

                    x2:
                        end.x,

                    y2:
                        end.y,

                    color:
                        s19DiagramState.color
                };

                frame.zones.push(
                    zone
                );

                s19DiagramState.selectedId =
                    zone.id;

            } else {

                const arrow = {
                    id:
                        s19Uid(
                            "diagram-arrow"
                        ),

                    x1:
                        start.x,

                    y1:
                        start.y,

                    x2:
                        end.x,

                    y2:
                        end.y,

                    style:
                        s19DiagramState.tool,

                    color:
                        s19DiagramState.color,

                    width:
                        4
                };

                frame.arrows.push(
                    arrow
                );

                s19DiagramState.selectedId =
                    arrow.id;

            }

            s19DiagramState.tool =
                "select";

            s13Save();

            s19RenderDiagramBoard(
                exercise
            );

        }
    );

}


/* =========================================================
   EXERCISE BOARD – INJECT INTO V17 EXERCISE EDITOR
========================================================= */

function s19InjectExerciseDesigner() {

    const exercise =
        s19ExerciseForDesigner();

    if (
        !exercise
    ) {
        return;
    }

    /*
        Put designer before media section if possible.
    */
    const mediaSection =
        document.querySelector(
            ".s17-media-section"
        );

    const saveArea =
        document.getElementById(
            "s17SaveExercise"
        )
            ?.parentElement;

    const parent =
        mediaSection
            ?.parentElement ||
        saveArea
            ?.parentElement;

    if (
        !parent
    ) {
        return;
    }

    let section =
        document.getElementById(
            "s19ExerciseDesigner"
        );

    if (!section) {

        section =
            document.createElement(
                "section"
            );

        section.id =
            "s19ExerciseDesigner";

        section.className =
            "s19-diagram-section";

        section.innerHTML = `
            <div id="s19DiagramHost"></div>
        `;

        if (
            mediaSection
        ) {

            parent.insertBefore(
                section,
                mediaSection
            );

        } else {

            parent.insertBefore(
                section,
                saveArea ||
                null
            );

        }

    }

    s19RenderDiagramBoard(
        exercise
    );

}


if (
    typeof s13Exercises ===
    "function"
) {

    const s19ExercisesBefore =
        s13Exercises;

    s13Exercises =
        function (
            target
        ) {

            const result =
                s19ExercisesBefore(
                    target
                );

            setTimeout(
                () => {

                    s19EnsureData();

                    s19InjectExerciseDesigner();

                },
                0
            );

            return result;

        };

}


/* =========================================================
   EXERCISE BOARD – PDF INTEGRATION
========================================================= */

if (
    typeof s17ExercisePdfMedia ===
    "function"
) {

    const s19PdfMediaBefore =
        s17ExercisePdfMedia;

    s17ExercisePdfMedia =
        async function (
            exercise
        ) {

            const media =
                await s19PdfMediaBefore(
                    exercise
                );

            const diagram =
                s19NormalizeDiagram(
                    exercise?.diagram
                );

            const frames =
                diagram.frames ||
                [];

            const diagramHtml =
                frames
                    .map(
                        (
                            frame,
                            index
                        ) => `
                            <div
                                style="
                                    margin-top:${index ? "4mm" : "0"};
                                    page-break-inside:avoid;
                                "
                            >
                                ${
                                    frames.length >
                                    1
                                        ? `
                                            <div
                                                style="
                                                    margin:0 0 1.5mm;
                                                    color:#666;
                                                    font-size:8px;
                                                    font-weight:900;
                                                    letter-spacing:.3px;
                                                "
                                            >
                                                ${
                                                    s13Esc(
                                                        frame.title ||
                                                        `TRIN ${index + 1}`
                                                    )
                                                }
                                                ${
                                                    Number(
                                                        frame.duration ||
                                                        0
                                                    )
                                                        ? ` · ${Number(frame.duration)} SEK`
                                                        : ""
                                                }
                                            </div>
                                        `
                                        : ""
                                }

                                ${
                                    s19PitchSvg(
                                        diagram.pitch,
                                        frame,
                                        index
                                    )
                                }
                            </div>
                        `
                    )
                    .join(
                        ""
                    );

            return {
                ...media,

                imageHtml:
                    (
                        diagramHtml
                            ? `
                                <div
                                    style="
                                        margin-bottom:4mm;
                                    "
                                >
                                    ${diagramHtml}
                                </div>
                            `
                            : ""
                    ) +
                    (
                        media.imageHtml ||
                        ""
                    )
            };

        };

}


/* =========================================================
   MATCH-SPECIFIC START11 – STATE
========================================================= */

const s19MatchMode = {
    active:
        false,

    key:
        "",

    match:
        null,

    baseWorkspace:
        null,

    enteredAt:
        null,

    saveTimer:
        null
};


/*
    Bevar V16's gamle kampplan-handler.
*/
const s19OpenLegacyMatchPlan =
    typeof start11CalendarApplyMatchToEditor ===
    "function"
        ? start11CalendarApplyMatchToEditor
        : null;


/* =========================================================
   MATCH-SPECIFIC START11 – HELPERS
========================================================= */

function s19MatchKey(
    match
) {

    if (
        typeof s16MatchPlanKey ===
        "function"
    ) {

        return s16MatchPlanKey(
            match
        );

    }

    const normalized =
        typeof start11CalendarNormalizeMatch ===
            "function"
            ? start11CalendarNormalizeMatch(
                match
            )
            : match;

    return String(
        normalized?.id ||
        normalized?.matchNumber ||
        [
            normalized?.date ||
                "",
            normalized?.home ||
                "",
            normalized?.away ||
                "",
            normalized?.time ||
                ""
        ]
            .join(
                "::"
            )
    );

}


function s19NormalizedMatch(
    match
) {

    return typeof start11CalendarNormalizeMatch ===
        "function"
        ? start11CalendarNormalizeMatch(
            match
        )
        : match;

}


function s19Opponent(
    match
) {

    const normalized =
        s19NormalizedMatch(
            match
        );

    if (
        typeof start11CalendarOpponent ===
        "function"
    ) {
        return start11CalendarOpponent(
            normalized
        );
    }

    const own =
        typeof start11CalendarTeamName ===
            "function"
            ? start11CalendarTeamName()
            : "";

    if (
        String(
            normalized?.home ||
            ""
        )
            .toLowerCase() ===
        String(
            own
        )
            .toLowerCase()
    ) {

        return normalized?.away ||
            "Modstander";

    }

    return normalized?.home ||
        "Modstander";

}


function s19SnapshotCurrentWorkspace() {

    return {
        spillere:
            s19Clone(
                spillere
            ),

        udskiftere:
            s19Clone(
                udskiftere
            ),

        formation:
            formationSelector.value ||
            currentFormation ||
            "4-4-2"
    };

}


function s19ApplyWorkspace(
    workspace
) {

    if (!workspace) {
        return;
    }

    spillere =
        Array.isArray(
            workspace.spillere
        )
            ? s19Clone(
                workspace.spillere
            )
            : Array(
                11
            )
                .fill(
                    null
                );

    udskiftere =
        Array.isArray(
            workspace.udskiftere
        )
            ? s19Clone(
                workspace.udskiftere
            )
            : [];

    currentFormation =
        workspace.formation ||
        "4-4-2";

    formationSelector.value =
        currentFormation;

    /*
        Her gemmer vi IKKE i localStorage.
        Match mode er kun en midlertidig editor.
    */
    tegnOpstilling();

    opdaterUdskiftere();

}


function s19MatchLineupRecord(
    key
) {

    s19EnsureData();

    return s13Data.matchLineups.find(
        item =>
            String(
                item.key
            ) ===
            String(
                key
            )
    ) ||
    null;

}


function s19CreateMatchLineupRecord(
    match,
    seed
) {

    const normalized =
        s19NormalizedMatch(
            match
        );

    const record = {
        id:
            s19Uid(
                "match-lineup"
            ),

        key:
            s19MatchKey(
                normalized
            ),

        matchId:
            normalized?.id ||
            "",

        date:
            normalized?.date ||
            "",

        time:
            normalized?.time ||
            "",

        home:
            normalized?.home ||
            "",

        away:
            normalized?.away ||
            "",

        opponent:
            s19Opponent(
                normalized
            ),

        status:
            "planned",

        formation:
            seed?.formation ||
            formationSelector.value ||
            "4-4-2",

        spillere:
            s19Clone(
                seed?.spillere ||
                spillere
            ),

        udskiftere:
            s19Clone(
                seed?.udskiftere ||
                udskiftere
            ),

        createdAt:
            new Date()
                .toISOString(),

        updatedAt:
            new Date()
                .toISOString()
    };

    s13Data.matchLineups.push(
        record
    );

    s13Save();

    return record;

}


function s19SaveActiveMatchLineup(
    notify = false
) {

    if (
        !s19MatchMode.active ||
        !s19MatchMode.key
    ) {
        return;
    }

    let record =
        s19MatchLineupRecord(
            s19MatchMode.key
        );

    if (!record) {

        record =
            s19CreateMatchLineupRecord(
                s19MatchMode.match,
                s19SnapshotCurrentWorkspace()
            );

    }

    record.formation =
        formationSelector.value ||
        currentFormation ||
        "4-4-2";

    record.spillere =
        s19Clone(
            spillere
        );

    record.udskiftere =
        s19Clone(
            udskiftere
        );

    record.updatedAt =
        new Date()
            .toISOString();

    s13Save();

    if (
        typeof scheduleCloudSave ===
        "function"
    ) {
        scheduleCloudSave();
    }

    s19UpdateMatchBar(
        notify
            ? "GEMT"
            : "AUTO-GEMT"
    );

    if (
        notify
    ) {

        visNotification?.(
            "Kampopstillingen er gemt."
        );

    }

}


function s19LatestPreviousLineup(
    currentMatch
) {

    const current =
        s19NormalizedMatch(
            currentMatch
        );

    const currentDate =
        String(
            current?.date ||
            ""
        );

    return [
        ...(
            s13Data.matchLineups ||
            []
        )
    ]
        .filter(
            record =>
                record.key !==
                    s19MatchMode.key &&
                (
                    !currentDate ||
                    !record.date ||
                    record.date <=
                    currentDate
                )
        )
        .sort(
            (
                a,
                b
            ) =>
                String(
                    b.date ||
                    b.updatedAt ||
                    ""
                )
                    .localeCompare(
                        String(
                            a.date ||
                            a.updatedAt ||
                            ""
                        )
                    )
        )[0] ||
        null;

}


/* =========================================================
   MATCH-SPECIFIC START11 – BAR
========================================================= */

function s19EnsureMatchBar() {

    let bar =
        document.getElementById(
            "s19MatchModeBar"
        );

    if (
        bar
    ) {
        return bar;
    }

    bar =
        document.createElement(
            "div"
        );

    bar.id =
        "s19MatchModeBar";

    /*
        Læg den lige før hovedindholdet når muligt.
    */
    const anchor =
        document.querySelector(
            "main"
        ) ||
        document.body.firstElementChild;

    if (
        anchor?.parentElement
    ) {

        anchor.parentElement.insertBefore(
            bar,
            anchor
        );

    } else {

        document.body.prepend(
            bar
        );

    }

    return bar;

}


function s19UpdateMatchBar(
    stateText = ""
) {

    const bar =
        s19EnsureMatchBar();

    if (
        !s19MatchMode.active
    ) {

        bar.classList.remove(
            "open"
        );

        return;
    }

    const match =
        s19NormalizedMatch(
            s19MatchMode.match
        );

    const opponent =
        s19Opponent(
            match
        );

    const record =
        s19MatchLineupRecord(
            s19MatchMode.key
        );

    bar.innerHTML = `

        <div class="s19-match-context">

            <div class="s19-match-badge">
                KAMP
            </div>

            <div
                style="
                    min-width:0;
                "
            >

                <div class="s19-match-title">
                    START11 · ${
                        s13Esc(
                            opponent
                        )
                    }
                </div>

                <div class="s19-match-sub">
                    ${
                        match?.date
                            ? s13Date(
                                match.date
                            )
                            : ""
                    }
                    ${
                        match?.time
                            ? ` · ${s13Esc(
                                match.time
                            )}`
                            : ""
                    }
                    ${
                        match?.place
                            ? ` · ${s13Esc(
                                match.place
                            )}`
                            : ""
                    }
                </div>

            </div>

            <div
                class="s19-match-save-state"
                id="s19MatchSaveState"
            >
                ${
                    stateText ||
                    (
                        record
                            ? "KAMP-SPECIFIK OPSTILLING"
                            : "NY KAMPPLAN"
                    )
                }
            </div>

        </div>


        <div class="s19-match-actions">

            <button
                type="button"
                id="s19MatchCopyPrevious"
                class="s13btn"
            >
                KOPIÉR SENESTE XI
            </button>

            <button
                type="button"
                id="s25MatchSituationsButton"
                class="s13btn"
            >
                KAMPSITUATIONER
            </button>

            <button
                type="button"
                id="s19MatchPlanButton"
                class="s13btn"
            >
                KAMPPLAN / PDF
            </button>

            <button
                type="button"
                id="s19MatchSaveButton"
                class="s13btn primary"
            >
                GEM OPSTILLING
            </button>

            <button
                type="button"
                id="s19MatchExitButton"
                class="s13btn"
            >
                AFSLUT KAMP
            </button>

        </div>
    `;

    bar.classList.add(
        "open"
    );

    document.getElementById(
        "s19MatchSaveButton"
    )
        ?.addEventListener(
            "click",
            () =>
                s19SaveActiveMatchLineup(
                    true
                )
        );

    document.getElementById(
        "s19MatchExitButton"
    )
        ?.addEventListener(
            "click",
            () =>
                s19ExitMatchMode(
                    true
                )
        );

    document.getElementById(
        "s25MatchSituationsButton"
    )
        ?.addEventListener(
            "click",
            () => {
                if (typeof window.s25OpenMatchSituations === "function") {
                    window.s25OpenMatchSituations();
                }
            }
        );


    document.getElementById(
        "s19MatchPlanButton"
    )
        ?.addEventListener(
            "click",
            () => {

                s19SaveActiveMatchLineup();

                if (
                    typeof s19OpenLegacyMatchPlan ===
                    "function"
                ) {

                    s19OpenLegacyMatchPlan(
                        s19MatchMode.match
                    );

                }

            }
        );

    document.getElementById(
        "s19MatchCopyPrevious"
    )
        ?.addEventListener(
            "click",
            () => {

                const previous =
                    s19LatestPreviousLineup(
                        s19MatchMode.match
                    );

                if (
                    !previous
                ) {

                    visNotification?.(
                        "Der findes ingen tidligere kampopstilling at kopiere."
                    );

                    return;
                }

                if (
                    !window.confirm(
                        `Kopiér opstillingen fra ${previous.opponent || "seneste kamp"}?`
                    )
                ) {
                    return;
                }

                s19ApplyWorkspace({
                    formation:
                        previous.formation,

                    spillere:
                        previous.spillere,

                    udskiftere:
                        previous.udskiftere
                });

                s19SaveActiveMatchLineup(
                    true
                );

            }
        );

}


/* =========================================================
   MATCH-SPECIFIC START11 – ENTER / EXIT
========================================================= */

function s19EnterMatchMode(
    match
) {

    s19EnsureData();

    const normalized =
        s19NormalizedMatch(
            match
        );

    const key =
        s19MatchKey(
            normalized
        );

    /*
        Hvis vi allerede er i en anden kamp:
        gem den først, men behold base-workspace.
    */
    if (
        s19MatchMode.active
    ) {

        s19SaveActiveMatchLineup();

    } else {

        s19MatchMode.baseWorkspace =
            s19SnapshotCurrentWorkspace();

    }

    let record =
        s19MatchLineupRecord(
            key
        );

    if (!record) {

        record =
            s19CreateMatchLineupRecord(
                normalized,
                s19MatchMode.baseWorkspace
            );

    }

    s19MatchMode.active =
        true;

    s19MatchMode.key =
        key;

    s19MatchMode.match =
        normalized;

    s19MatchMode.enteredAt =
        new Date()
            .toISOString();

    s19ApplyWorkspace({
        formation:
            record.formation,

        spillere:
            record.spillere,

        udskiftere:
            record.udskiftere
    });

    s19UpdateMatchBar(
        "KAMP-SPECIFIK OPSTILLING"
    );

    /*
        Luk kalenderen og gå til START11-banen.
    */
    if (
        typeof start11CalendarSetOpen ===
        "function"
    ) {

        start11CalendarSetOpen(
            false
        );

    }

    const pitchTarget =
        document.getElementById(
            "pitch"
        )
            ?.closest(
                "section, .panel, .card, main, div"
            ) ||
        document.getElementById(
            "pitch"
        );

    setTimeout(
        () => {

            pitchTarget
                ?.scrollIntoView({
                    behavior:
                        "smooth",
                    block:
                        "start"
                });

        },
        50
    );

    visNotification?.(
        `Kampopstilling åbnet: ${s19Opponent(normalized)}`
    );

}


function s19ExitMatchMode(
    saveFirst = true
) {

    if (
        !s19MatchMode.active
    ) {
        return;
    }

    if (
        saveFirst
    ) {
        s19SaveActiveMatchLineup();
    }

    const base =
        s19MatchMode.baseWorkspace;

    s19MatchMode.active =
        false;

    s19MatchMode.key =
        "";

    s19MatchMode.match =
        null;

    s19MatchMode.enteredAt =
        null;

    s19MatchMode.baseWorkspace =
        null;

    if (
        base
    ) {

        s19ApplyWorkspace(
            base
        );

        /*
            Gendan holdets normale lokale arbejdskopi.
        */
        localStorage.setItem(
            "startopstillingSpillere",
            JSON.stringify(
                spillere
            )
        );

        localStorage.setItem(
            "startopstillingUdskiftere",
            JSON.stringify(
                udskiftere
            )
        );

        localStorage.setItem(
            "start11Formation",
            formationSelector.value
        );

    }

    s19UpdateMatchBar();

    visNotification?.(
        "Tilbage til holdets normale START11."
    );

}


/* =========================================================
   MATCH-SPECIFIC START11 – GEMALT OVERRIDE
========================================================= */

if (
    typeof gemAlt ===
    "function"
) {

    const s19GemAltBefore =
        gemAlt;

    gemAlt =
        function () {

            if (
                s19MatchMode.active
            ) {

                /*
                    Match-mode må IKKE overskrive holdets
                    normale START11 i localStorage/cloud.
                */
                clearTimeout(
                    s19MatchMode.saveTimer
                );

                s19MatchMode.saveTimer =
                    setTimeout(
                        () =>
                            s19SaveActiveMatchLineup(),
                        160
                    );

                return;

            }

            return s19GemAltBefore();

        };

}


/*
    Ekstra sikkerhedsnet:
    Hvis en anden funktion kalder collectTeamData direkte mens
    match-mode er åben, skal cloud stadig få holdets NORMALE XI.
*/
if (
    typeof collectTeamData ===
    "function"
) {

    const s19CollectBefore =
        collectTeamData;

    collectTeamData =
        function () {

            const collected =
                s19CollectBefore();

            if (
                !s19MatchMode.active ||
                !s19MatchMode.baseWorkspace
            ) {
                return collected;
            }

            return {
                ...collected,

                spillere:
                    s19Clone(
                        s19MatchMode.baseWorkspace
                            .spillere
                    ),

                udskiftere:
                    s19Clone(
                        s19MatchMode.baseWorkspace
                            .udskiftere
                    ),

                formation:
                    s19MatchMode.baseWorkspace
                        .formation
            };

        };

}


/*
    Holdskift: fjern kamp-mode uden at forsøge at gendanne det
    forrige holds workspace EFTER det nye hold er indlæst.
*/
if (
    typeof applyTeamData ===
    "function"
) {

    const s19ApplyTeamDataBefore =
        applyTeamData;

    applyTeamData =
        function (
            data
        ) {

            if (
                s19MatchMode.active
            ) {

                s19SaveActiveMatchLineup();

                s19MatchMode.active =
                    false;

                s19MatchMode.key =
                    "";

                s19MatchMode.match =
                    null;

                s19MatchMode.baseWorkspace =
                    null;

                s19UpdateMatchBar();

            }

            const result =
                s19ApplyTeamDataBefore(
                    data
                );

            setTimeout(
                s19EnsureData,
                0
            );

            return result;

        };

}


/* =========================================================
   MATCH-SPECIFIC START11 – CALENDAR CLICK OVERRIDE
========================================================= */

/*
    Fra V19 betyder klik på en kamp:
    ÅBN DEN KAMP-SPECIFIKKE START11.

    Den gamle kampplan findes stadig via knappen
    "KAMPPLAN / PDF" i match-mode baren.
*/
start11CalendarApplyMatchToEditor =
    function (
        match
    ) {

        s19EnterMatchMode(
            match
        );

    };


/* =========================================================
   MATCH-SPECIFIC START11 – VIS BADGE PÅ KALENDERKAMPE
========================================================= */

function s19DecorateCalendarMatchLineups() {

    s19EnsureData();

    const calendar =
        document.getElementById(
            "start11CalendarShell"
        );

    if (!calendar) {
        return;
    }

    /*
        Brug tekst/date mapping frem for at ændre eksisterende
        kalenderstruktur aggressivt.
    */
    const records =
        s13Data.matchLineups ||
        [];

    calendar.querySelectorAll(
        "button, [role='button'], .start11-calendar-day > div, .start11-calendar-match, .start11-calendar-month-match"
    )
        .forEach(
            node => {

                if (
                    node.querySelector?.(
                        ".s19-lineup-badge"
                    )
                ) {
                    return;
                }

                const text =
                    String(
                        node.textContent ||
                        ""
                    )
                        .toLowerCase();

                const match =
                    records.find(
                        record => {

                            const opponent =
                                String(
                                    record.opponent ||
                                    ""
                                )
                                    .toLowerCase();

                            return (
                                opponent &&
                                text.includes(
                                    opponent
                                )
                            );

                        }
                    );

                if (!match) {
                    return;
                }

                const badge =
                    document.createElement(
                        "span"
                    );

                badge.className =
                    "s19-lineup-badge";

                badge.textContent =
                    "START11";

                Object.assign(
                    badge.style,
                    {
                        display:
                            "inline-flex",

                        marginLeft:
                            "5px",

                        padding:
                            "2px 5px",

                        border:
                            "1px solid var(--s11-primary)",

                        borderRadius:
                            "999px",

                        color:
                            "var(--s11-primary)",

                        fontSize:
                            "6px",

                        fontWeight:
                            "950",

                        verticalAlign:
                            "middle"
                    }
                );

                node.appendChild(
                    badge
                );

            }
        );

}


/*
    Kalender render wrap – behold V15/V16 funktionalitet.
*/
if (
    typeof start11RenderCalendarV3 ===
    "function"
) {

    const s19RenderCalendarBefore =
        start11RenderCalendarV3;

    start11RenderCalendarV3 =
        function (
            ...args
        ) {

            const result =
                s19RenderCalendarBefore(
                    ...args
                );

            setTimeout(
                s19DecorateCalendarMatchLineups,
                50
            );

            return result;

        };

}


/* =========================================================
   MATCH LINEUP – OPTIONAL QUICK SUMMARY IN COACHING HUB
========================================================= */

function s19MatchLineupSummary(
    match
) {

    const key =
        s19MatchKey(
            match
        );

    const record =
        s19MatchLineupRecord(
            key
        );

    if (!record) {
        return "";
    }

    const starters =
        (
            record.spillere ||
            []
        )
            .filter(
                Boolean
            )
            .length;

    const subs =
        (
            record.udskiftere ||
            []
        )
            .filter(
                Boolean
            )
            .length;

    return `${record.formation || "—"} · ${starters} startere · ${subs} udskiftere`;

}


/* =========================================================
   INIT
========================================================= */

function s19Init() {

    s19EnsureData();

    s19InstallStyles();

    s19EnsureMatchBar();

    /*
        Sørg for at øvelsesdesigner bliver tilføjet hvis brugeren
        allerede står på en øvelse når V19 init kører.
    */
    if (
        document.getElementById(
            "s17SaveExercise"
        )
    ) {

        s19InjectExerciseDesigner();

    }

    /*
        Let observer – kun relevante renderpunkter.
    */
    let timer =
        null;

    const observer =
        new MutationObserver(
            mutations => {

                const relevant =
                    mutations.some(
                        mutation =>
                            [
                                ...mutation.addedNodes
                            ]
                                .some(
                                    node => {

                                        if (
                                            !(
                                                node instanceof
                                                Element
                                            )
                                        ) {
                                            return false;
                                        }

                                        return (
                                            node.id ===
                                                "s17SaveExercise" ||
                                            node.id ===
                                                "start11CalendarShell" ||
                                            node.querySelector?.(
                                                "#s17SaveExercise,#start11CalendarShell"
                                            )
                                        );

                                    }
                                )
                    );

                if (!relevant) {
                    return;
                }

                clearTimeout(
                    timer
                );

                timer =
                    setTimeout(
                        () => {

                            if (
                                document.getElementById(
                                    "s17SaveExercise"
                                )
                            ) {

                                s19InjectExerciseDesigner();

                            }

                            s19DecorateCalendarMatchLineups();

                        },
                        90
                    );

            }
        );

    observer.observe(
        document.body,
        {
            childList:
                true,

            subtree:
                true
        }
    );

}


if (
    document.readyState ===
    "loading"
) {

    document.addEventListener(
        "DOMContentLoaded",
        () =>
            setTimeout(
                s19Init,
                3350
            )
    );

} else {

    setTimeout(
        s19Init,
        3350
    );

}


/* =========================================================
   START11 – V20 COACH OPERATING SYSTEM
   Dashboard · Live Match Centre · Post-match review
   Principbibliotek · Sæsonplan · Træningsstatistik
   Spillerudvikling 2.0 · Spillersamtaler
   Smart øvelsesbank · Modstanderscouting · Coach Intelligence
========================================================= */

function s20EnsureData(){
  if(!s13Data||typeof s13Data!=="object")s13Data={};
  ["liveMatches","opponentProfiles","seasonPlan","trainingEvaluations","intelligenceNotes"].forEach(k=>{
    if(!Array.isArray(s13Data[k]))s13Data[k]=[];
  });
  if(!Array.isArray(s13Data.principles))s13Data.principles=[];
  if(!Array.isArray(s13Data.exercises))s13Data.exercises=[];
  s13Data.principles.forEach(p=>{
    p.coachingPoints=String(p.coachingPoints||"");
    p.triggers=String(p.triggers||"");
    p.tags=String(p.tags||"");
    p.exerciseIds=Array.isArray(p.exerciseIds)?p.exerciseIds:[];
    p.videoClipIds=Array.isArray(p.videoClipIds)?p.videoClipIds:[];
  });
  s13Data.exercises.forEach(e=>{
    e.tags=String(e.tags||"");
    e.intensity=e.intensity||"Mellem";
    e.ageLevel=String(e.ageLevel||"");
    e.playerMin=Number(e.playerMin||0);
    e.playerMax=Number(e.playerMax||0);
  });
}
if(typeof s13Norm==="function"){
  const _s20norm=s13Norm;
  s13Norm=function(raw={}){
    const d=_s20norm(raw);
    d.liveMatches=Array.isArray(raw.liveMatches)?raw.liveMatches:[];
    d.opponentProfiles=Array.isArray(raw.opponentProfiles)?raw.opponentProfiles:[];
    d.seasonPlan=Array.isArray(raw.seasonPlan)?raw.seasonPlan:[];
    d.trainingEvaluations=Array.isArray(raw.trainingEvaluations)?raw.trainingEvaluations:[];
    d.intelligenceNotes=Array.isArray(raw.intelligenceNotes)?raw.intelligenceNotes:[];
    return d;
  };
}

const s20State={
  liveId:null,scoutingId:null,seasonId:null,developmentPlayerId:null,
  developmentAttribute:"",liveTicker:null,
  exerciseFilter:{search:"",theme:"",intensity:"",players:"",tags:""}
};

function s20InstallStyles(){
  if(document.getElementById("s20styles"))return;
  const s=document.createElement("style");s.id="s20styles";s.textContent=`
  .s20dash{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}
  .s20card,.s20metric,.s20insight{padding:12px;border:1px solid rgba(255,255,255,.075);border-radius:8px;background:#071009}
  .s20label{color:#78847c;font-size:7px;font-weight:950;text-transform:uppercase;letter-spacing:.4px}
  .s20value{margin-top:5px;color:#fff;font-size:20px;font-weight:1000}.s20value.accent{color:var(--s11-primary)}
  .s20metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
  .s20metric span{display:block;color:#78847c;font-size:7px;font-weight:900}.s20metric strong{display:block;margin-top:4px;color:var(--s11-primary);font-size:17px}
  .s20progress{height:7px;border-radius:999px;background:rgba(255,255,255,.07);overflow:hidden}.s20progress span{display:block;height:100%;background:linear-gradient(90deg,var(--s11-primary),var(--s11-secondary))}
  .s20dist{display:grid;grid-template-columns:120px minmax(0,1fr) 50px;gap:8px;align-items:center;font-size:7px}
  .s20insight{border-left:3px solid var(--s11-primary)}.s20insight.high{border-left-color:#ff6868}.s20insight.medium{border-left-color:#f0c45e}
  .s20insight strong{font-size:9px}.s20insight p{margin:5px 0 0;color:#99a59c;font-size:8px;line-height:1.5}
  .s20flow{display:flex;gap:5px;overflow:auto}.s20step{min-width:145px;padding:10px;border:1px solid rgba(255,255,255,.07);border-radius:7px;background:#08100a}
  .s20arrow{display:grid;place-items:center;color:var(--s11-primary);font-weight:1000}
  .s20live{display:grid;grid-template-columns:1fr auto 1fr;gap:14px;align-items:center;text-align:center;padding:20px;border:1px solid rgba(255,255,255,.08);border-radius:10px;background:#061008}
  .s20team{font-size:17px;font-weight:1000}.s20score{font-size:38px;font-weight:1000;color:var(--s11-primary);font-variant-numeric:tabular-nums}.s20clock{font-size:10px;color:#98a39a}
  .s20event{display:grid;grid-template-columns:48px 90px minmax(0,1fr) auto;gap:8px;align-items:center;padding:8px;border:1px solid rgba(255,255,255,.06);border-radius:6px;background:#071009}
  .s20season{display:grid;grid-template-columns:110px minmax(0,1fr) 80px auto;gap:9px;align-items:center;padding:10px;border:1px solid rgba(255,255,255,.07);border-radius:7px;background:#071009}
  .s20filters{display:grid;grid-template-columns:1.5fr repeat(4,minmax(100px,1fr));gap:7px}
  .s20checklist{max-height:180px;overflow:auto;padding:7px;border:1px solid rgba(255,255,255,.07);border-radius:6px;background:#050905}
  .s20check{display:flex;align-items:center;gap:7px;min-height:27px;color:#aab5ac;font-size:7px}
  .s20chart{height:240px;border:1px solid rgba(255,255,255,.06);border-radius:7px;background:#050905;overflow:hidden}.s20chart svg{width:100%;height:100%}
  @media(max-width:1100px){.s20dash{grid-template-columns:repeat(2,minmax(0,1fr))}.s20filters{grid-template-columns:1fr}}
  @media(max-width:700px){.s20dash,.s20metrics{grid-template-columns:1fr}.s20live,.s20event,.s20season{grid-template-columns:1fr}}
  `;document.head.appendChild(s);
}

function s20UpcomingMatches(){
  if(typeof start11CalendarAllMatches!=="function")return[];
  return start11CalendarAllMatches().map(m=>typeof start11CalendarNormalizeMatch==="function"?start11CalendarNormalizeMatch(m):m)
    .filter(m=>String(m.date||"")>=s13Today())
    .sort((a,b)=>String(a.date||"").localeCompare(String(b.date||""))||String(a.time||"").localeCompare(String(b.time||"")));
}
const s20NextMatch=()=>s20UpcomingMatches()[0]||null;
function s20Opponent(m){
  if(!m)return"";
  if(typeof start11CalendarOpponent==="function")return start11CalendarOpponent(m);
  return m.away||m.home||"";
}
const s20SessionMinutes=s=>(s?.blocks||[]).reduce((n,b)=>n+Number(b.duration||0),0);
const s20AllClips=()=>Array.isArray(s13Data.videoProjects)?s13Data.videoProjects.flatMap(p=>(p.clips||[]).map(c=>({...c,projectId:p.id,projectTitle:p.title||"Video"}))):[];
const s20SessionEval=id=>s13Data.trainingEvaluations.find(x=>x.sessionId===id)||null;

function s20LineChart(points){
  if(!points.length)return`<div style="height:100%;display:grid;place-items:center;color:#748078;font-size:8px">Ingen historik endnu.</div>`;
  const W=760,H=240,P=34, sx=i=>points.length===1?W/2:P+i*(W-2*P)/(points.length-1), sy=v=>H-P-(Number(v||0)/100)*(H-2*P);
  const path=points.map((p,i)=>(i?"L":"M")+sx(i)+","+sy(p.value)).join(" ");
  return`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">
    <line x1="${P}" y1="${H-P}" x2="${W-P}" y2="${H-P}" stroke="rgba(255,255,255,.1)"/>
    <path d="${path}" fill="none" stroke="var(--s11-primary)" stroke-width="4" stroke-linecap="round"/>
    ${points.map((p,i)=>`<circle cx="${sx(i)}" cy="${sy(p.value)}" r="4" fill="var(--s11-primary)"/>
      <text x="${sx(i)}" y="${sy(p.value)-9}" text-anchor="middle" fill="#fff" font-size="11">${Math.round(p.value)}</text>
      <text x="${sx(i)}" y="${H-9}" text-anchor="middle" fill="#77837b" font-size="9">${s13Esc(p.label||"")}</text>`).join("")}
  </svg>`;
}

/* =========================================================
   COACHING HUB NAV
========================================================= */
s13Render=function(){
  const meta=s13Meta(),top=document.getElementById("s13top"),tabs=document.getElementById("s13tabs");
  if(top)top.innerHTML=`<div><h2>COACHING HUB</h2><div class="s13mut">${s13Esc(meta.clubName)} · ${s13Esc(meta.teamName)} · coach operating system</div></div>
  <div><button id="s13quick" class="s13btn primary">+ TRÆNING</button> <button id="s20quicklive" class="s13btn">LIVE KAMP</button> <button id="s13close" class="s13btn">LUK</button></div>`;
  document.getElementById("s13close")?.addEventListener("click",s13Close);
  document.getElementById("s13quick")?.addEventListener("click",()=>{s13Tab="training";s13Session=null;s13Render();setTimeout(s13EditSession,0)});
  document.getElementById("s20quicklive")?.addEventListener("click",()=>{s13Tab="live";s13Render()});
  const list=[["dashboard","DASHBOARD"],["training","TRÆNING"],["exercises","ØVELSESBANK"],["attendance","FREMMØDE"],["principles","PRINCIPPER"],["live","LIVE KAMP"],["matches","KAMPANALYSE"],["season","SÆSONPLAN"],["scouting","SCOUTING"],["matrix","UDVIKLING"],["videos","VIDEO"],["meetings","SAMTALER"],["intelligence","INTELLIGENCE"]];
  if(tabs){tabs.innerHTML=list.map(([id,l])=>`<button class="s13tab ${s13Tab===id?"active":""}" data-t="${id}">${l}</button>`).join("");tabs.querySelectorAll("[data-t]").forEach(b=>b.onclick=()=>{s13Tab=b.dataset.t;s13Render()})}
  s13RenderContent();s13Home();
};
s13RenderContent=function(){
  const t=document.getElementById("s13content");if(!t)return;
  const map={dashboard:s20Dashboard,training:s13Training,exercises:s13Exercises,attendance:s13Attendance,principles:s20Principles,live:s20Live,matches:s13Matches,season:s20Season,scouting:s20Scouting,matrix:s20Development,videos:s13Videos,meetings:s20Meetings,intelligence:s20Intelligence};
  (map[s13Tab]||s20Dashboard)(t);
};

