/* =========================================================
   V22 HELPERS
========================================================= */

function s22Projects(){

    s22EnsureData();

    return s13Data.videoProjects;

}


function s22CurrentProject(){

    const projects =
        s22Projects();

    if(
        s22State.projectId
    ){

        const found =
            projects.find(
                project =>
                    project.id ===
                    s22State.projectId
            );

        if(found){
            return found;
        }

    }

    const first =
        projects[0] ||
        null;

    if(first){
        s22State.projectId =
            first.id;
    }

    return first;

}


function s22Analytics(){

    const project =
        s22CurrentProject();

    if(!project){
        return null;
    }

    project.analytics =
        project.analytics ||
        {
            events:[],
            possessionSegments:[],
            aiRuns:[]
        };

    return project.analytics;

}


function s22OwnTeamName(){

    return (
        typeof start11CalendarTeamName ===
        "function"
            ? start11CalendarTeamName()
            : (
                s13Meta()
                    .teamName ||
                "START11"
            )
    );

}


function s22OpponentName(project){

    if(!project){
        return "Modstander";
    }

    return (
        project.opponent ||
        String(
            project.title ||
            ""
        )
            .split(
                "-"
            )[1]
            ?.trim() ||
        "Modstander"
    );

}


function s22FormatTime(seconds){

    const s =
        Math.max(
            0,
            Number(
                seconds ||
                0
            )
        );

    const h =
        Math.floor(
            s /
            3600
        );

    const m =
        Math.floor(
            (
                s %
                3600
            ) /
            60
        );

    const sec =
        Math.floor(
            s %
            60
        );

    return h
        ? `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}`
        : `${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}`;

}


function s22ZoneFromPoint(x,y){

    if(
        x == null ||
        y == null
    ){
        return "";
    }

    const third =
        x < .333
            ? "Defensiv tredjedel"
            : (
                x < .666
                    ? "Midterste tredjedel"
                    : "Offensiv tredjedel"
            );

    const lane =
        y < .20
            ? "Venstre yderside"
            : (
                y < .40
                    ? "Venstre halfspace"
                    : (
                        y < .60
                            ? "Centralt"
                            : (
                                y < .80
                                    ? "Højre halfspace"
                                    : "Højre yderside"
                            )
                    )
            );

    return `${third} · ${lane}`;

}


function s22EventMatchesFilter(event){

    if(
        s22State.eventFilter !==
            "all" &&
        event.type !==
            s22State.eventFilter
    ){
        return false;
    }

    if(
        s22State.teamFilter !==
            "all" &&
        event.team !==
            s22State.teamFilter
    ){
        return false;
    }

    if(
        Number(
            event.confidence ??
            1
        ) <
        s22State.minConfidence
    ){
        return false;
    }

    return true;

}


function s22FilteredEvents(){

    const a =
        s22Analytics();

    if(!a){
        return [];
    }

    return a.events
        .filter(
            s22EventMatchesFilter
        )
        .sort(
            (
                a,
                b
            ) =>
                Number(
                    a.time ||
                    0
                ) -
                Number(
                    b.time ||
                    0
                )
        );

}


function s22Count(type,team="own"){

    const a =
        s22Analytics();

    if(!a){
        return 0;
    }

    return a.events
        .filter(
            event =>
                event.type ===
                    type &&
                event.team ===
                    team
        )
        .length;

}


function s22CountAny(types,team="own"){

    const a =
        s22Analytics();

    if(!a){
        return 0;
    }

    return a.events
        .filter(
            event =>
                types.includes(
                    event.type
                ) &&
                event.team ===
                    team
        )
        .length;

}


function s22PossessionStats(){

    const a =
        s22Analytics();

    if(!a){
        return {
            own:
                0,
            opp:
                0
        };
    }

    let own =
        0;

    let opp =
        0;

    a.possessionSegments.forEach(
        segment => {

            const duration =
                Math.max(
                    0,
                    Number(
                        segment.end ||
                        0
                    ) -
                    Number(
                        segment.start ||
                        0
                    )
                );

            if(
                segment.team ===
                "own"
            ){
                own +=
                    duration;
            }else if(
                segment.team ===
                "opp"
            ){
                opp +=
                    duration;
            }

        }
    );

    /*
        Åben possession tælles frem til nuværende videotid.
    */
    if(
        s22State.possessionTeam &&
        s22State.possessionStartedAt != null
    ){

        const video =
            document.getElementById(
                "s22Video"
            );

        const current =
            video
                ? video.currentTime
                : s22State.possessionStartedAt;

        const duration =
            Math.max(
                0,
                current -
                s22State.possessionStartedAt
            );

        if(
            s22State.possessionTeam ===
            "own"
        ){
            own +=
                duration;
        }else{
            opp +=
                duration;
        }

    }

    const total =
        own +
        opp;

    return total
        ? {
            own:
                own /
                total *
                100,
            opp:
                opp /
                total *
                100
        }
        : {
            own:
                0,
            opp:
                0
        };

}


function s22EventLabel(type){

    return (
        s22EventTypes[
            type
        ]
            ?.label ||
        type ||
        "Event"
    );

}


/* =========================================================
   V22 VIDEO LOADING
========================================================= */

async function s22LoadVideo(){

    const project =
        s22CurrentProject();

    const stage =
        document.getElementById(
            "s22VideoStage"
        );

    if(
        !project ||
        !stage
    ){
        return;
    }

    if(
        s22State.objectUrl
    ){

        try{
            URL.revokeObjectURL(
                s22State.objectUrl
            );
        }catch(_){}

        s22State.objectUrl =
            "";

    }

    const source =
        project.matchVideo;

    if(!source){

        stage.innerHTML = `
            <div
                style="
                    width:100%;
                    height:100%;
                    display:grid;
                    place-items:center;
                    text-align:center;
                    color:#7c897f;
                    font-size:8px;
                "
            >
                Ingen hel kampvideo på dette projekt endnu.<br>
                Gå til VIDEO og importér kampen først.
            </div>
        `;

        return;
    }

    let src =
        "";

    if(
        source.sourceType ===
        "local"
    ){

        const stored =
            await s15GetBlob(
                source.mediaId
            );

        if(
            stored?.blob
        ){

            src =
                URL.createObjectURL(
                    stored.blob
                );

            s22State.objectUrl =
                src;

        }

    }else{

        src =
            source.url ||
            "";

    }

    if(!src){

        stage.innerHTML = `
            <div
                style="
                    width:100%;
                    height:100%;
                    display:grid;
                    place-items:center;
                    color:#7c897f;
                    font-size:8px;
                "
            >
                Videoen kunne ikke findes på denne enhed.
            </div>
        `;

        return;
    }

    stage.innerHTML = `
        <video
            id="s22Video"
            src="${
                s13Esc(
                    src
                )
            }"
            controls
            preload="metadata"
            playsinline
        ></video>
    `;

    const video =
        document.getElementById(
            "s22Video"
        );

    video?.addEventListener(
        "loadedmetadata",
        () => {

            s22RenderTimeline();

            s22UpdateDataPanels();

        }
    );

    video?.addEventListener(
        "timeupdate",
        () => {

            s22UpdatePlayhead();

            const label =
                document.getElementById(
                    "s22CurrentTime"
                );

            if(label){

                label.textContent =
                    s22FormatTime(
                        video.currentTime
                    );

            }

        }
    );

}


/* =========================================================
   V22 MANUAL EVENT TAGGING
========================================================= */

function s22SelectedTeam(){

    const a =
        s22Analytics();

    return (
        a?.selectedTeam ||
        "own"
    );

}


function s22SetSelectedTeam(team){

    const a =
        s22Analytics();

    if(!a){
        return;
    }

    a.selectedTeam =
        team;

    s13Save();

    s22RenderTeamToggle();

}


function s22CreateEvent(type){

    const project =
        s22CurrentProject();

    const a =
        s22Analytics();

    const video =
        document.getElementById(
            "s22Video"
        );

    if(
        !project ||
        !a ||
        !video
    ){
        return;
    }

    const time =
        Number(
            video.currentTime ||
            0
        );

    const team =
        s22SelectedTeam();

    let outcome =
        "";

    let note =
        "";

    let playerId =
        "";

    if(
        type ===
        "shot"
    ){

        outcome =
            window.prompt(
                "Skudresultat: goal / on_target / off_target / blocked",
                "on_target"
            ) ||
            "on_target";

        if(
            outcome ===
            "goal"
        ){
            type =
                "goal";
        }

    }else if(
        type ===
        "duel"
    ){

        outcome =
            window.prompt(
                "Duel: won / lost",
                "won"
            ) ||
            "";

    }else if(
        type ===
        "counterpress"
    ){

        outcome =
            window.prompt(
                "Genpres: won / escaped",
                "won"
            ) ||
            "";

    }else if(
        type ===
        "pass" ||
        type ===
        "progressive_pass"
    ){

        outcome =
            window.prompt(
                "Aflevering: complete / incomplete",
                "complete"
            ) ||
            "";

    }else if(
        type ===
        "note"
    ){

        note =
            window.prompt(
                "Observation:",
                ""
            ) ||
            "";

    }

    const playerName =
        window.prompt(
            "Spiller (valgfrit):",
            ""
        );

    if(
        playerName
    ){

        const player =
            s13Players()
                .find(
                    p =>
                        String(
                            p.name ||
                            ""
                        )
                            .trim()
                            .toLowerCase() ===
                        String(
                            playerName
                        )
                            .trim()
                            .toLowerCase()
                );

        playerId =
            player?.id ||
            "";

    }

    const point =
        s22State.pitchPoint;

    const event = {

        id:
            s13Id(
                "match-event"
            ),

        type,

        team,

        time,

        start:
            Math.max(
                0,
                time -
                6
            ),

        end:
            time +
            7,

        x:
            point?.x ??
            null,

        y:
            point?.y ??
            null,

        zone:
            point
                ? s22ZoneFromPoint(
                    point.x,
                    point.y
                )
                : "",

        outcome,

        note,

        playerId,

        source:
            "manual",

        confidence:
            1,

        createdAt:
            new Date().toISOString()

    };

    a.events.push(
        event
    );

    a.updatedAt =
        new Date().toISOString();

    s13Save();

    s22State.selectedEventId =
        event.id;

    s22RenderDataHub(
        document.getElementById(
            "s13content"
        )
    );

    setTimeout(
        () => {

            const v =
                document.getElementById(
                    "s22Video"
                );

            if(v){
                v.currentTime =
                    time;
            }

        },
        30
    );

}


function s22DeleteEvent(eventId){

    const a =
        s22Analytics();

    if(!a){
        return;
    }

    a.events =
        a.events.filter(
            event =>
                event.id !==
                eventId
        );

    if(
        s22State.selectedEventId ===
        eventId
    ){
        s22State.selectedEventId =
            null;
    }

    s13Save();

    s22RenderDataHub(
        document.getElementById(
            "s13content"
        )
    );

}


/* =========================================================
   V22 POSSESSION LOGGER
========================================================= */

function s22SwitchPossession(team){

    const a =
        s22Analytics();

    const video =
        document.getElementById(
            "s22Video"
        );

    if(
        !a ||
        !video
    ){
        return;
    }

    const now =
        Number(
            video.currentTime ||
            0
        );

    if(
        s22State.possessionTeam &&
        s22State.possessionStartedAt != null
    ){

        if(
            now >
            s22State.possessionStartedAt
        ){

            a.possessionSegments.push({

                id:
                    s13Id(
                        "possession"
                    ),

                team:
                    s22State.possessionTeam,

                start:
                    s22State.possessionStartedAt,

                end:
                    now,

                source:
                    "manual"

            });

        }

    }

    s22State.possessionTeam =
        team;

    s22State.possessionStartedAt =
        now;

    s13Save();

    s22UpdateDataPanels();

}


function s22StopPossession(){

    const a =
        s22Analytics();

    const video =
        document.getElementById(
            "s22Video"
        );

    if(
        !a ||
        !video ||
        !s22State.possessionTeam ||
        s22State.possessionStartedAt == null
    ){
        return;
    }

    const now =
        Number(
            video.currentTime ||
            0
        );

    if(
        now >
        s22State.possessionStartedAt
    ){

        a.possessionSegments.push({

            id:
                s13Id(
                    "possession"
                ),

            team:
                s22State.possessionTeam,

            start:
                s22State.possessionStartedAt,

            end:
                now,

            source:
                "manual"

        });

    }

    s22State.possessionTeam =
        null;

    s22State.possessionStartedAt =
        null;

    s13Save();

    s22UpdateDataPanels();

}


/* =========================================================
   V22 STATISTICS
========================================================= */

function s22Stats(){

    const ownShots =
        s22CountAny(
            [
                "shot",
                "goal"
            ],
            "own"
        );

    const oppShots =
        s22CountAny(
            [
                "shot",
                "goal"
            ],
            "opp"
        );

    const ownGoals =
        s22Count(
            "goal",
            "own"
        );

    const oppGoals =
        s22Count(
            "goal",
            "opp"
        );

    const ownOnTarget =
        s22Analytics()
            ?.events
            .filter(
                event =>
                    event.team ===
                        "own" &&
                    (
                        event.type ===
                            "goal" ||
                        (
                            event.type ===
                                "shot" &&
                            event.outcome ===
                                "on_target"
                        )
                    )
            )
            .length ||
        0;

    const oppOnTarget =
        s22Analytics()
            ?.events
            .filter(
                event =>
                    event.team ===
                        "opp" &&
                    (
                        event.type ===
                            "goal" ||
                        (
                            event.type ===
                                "shot" &&
                            event.outcome ===
                                "on_target"
                        )
                    )
            )
            .length ||
        0;

    const ownDuelWon =
        s22Analytics()
            ?.events
            .filter(
                event =>
                    event.team ===
                        "own" &&
                    event.type ===
                        "duel" &&
                    event.outcome ===
                        "won"
            )
            .length ||
        0;

    const ownDuels =
        s22Count(
            "duel",
            "own"
        );

    const oppDuelWon =
        s22Analytics()
            ?.events
            .filter(
                event =>
                    event.team ===
                        "opp" &&
                    event.type ===
                        "duel" &&
                    event.outcome ===
                        "won"
            )
            .length ||
        0;

    const oppDuels =
        s22Count(
            "duel",
            "opp"
        );

    const possession =
        s22PossessionStats();

    return {

        possession,

        ownShots,
        oppShots,

        ownGoals,
        oppGoals,

        ownOnTarget,
        oppOnTarget,

        ownCorners:
            s22Count(
                "corner",
                "own"
            ),

        oppCorners:
            s22Count(
                "corner",
                "opp"
            ),

        ownBallLoss:
            s22Count(
                "ball_loss",
                "own"
            ),

        oppBallLoss:
            s22Count(
                "ball_loss",
                "opp"
            ),

        ownRecoveries:
            s22Count(
                "recovery",
                "own"
            ),

        oppRecoveries:
            s22Count(
                "recovery",
                "opp"
            ),

        ownCounterpress:
            s22Analytics()
                ?.events
                .filter(
                    event =>
                        event.team ===
                            "own" &&
                        event.type ===
                            "counterpress" &&
                        event.outcome !==
                            "escaped"
                )
                .length ||
            0,

        oppCounterpress:
            s22Analytics()
                ?.events
                .filter(
                    event =>
                        event.team ===
                            "opp" &&
                        event.type ===
                            "counterpress" &&
                        event.outcome !==
                            "escaped"
                )
                .length ||
            0,

        ownDuelPct:
            ownDuels
                ? Math.round(
                    ownDuelWon /
                    ownDuels *
                    100
                )
                : 0,

        oppDuelPct:
            oppDuels
                ? Math.round(
                    oppDuelWon /
                    oppDuels *
                    100
                )
                : 0

    };

}


/* =========================================================
   V22 TIMELINE
========================================================= */

function s22RenderTimeline(){

    const timeline =
        document.getElementById(
            "s22Timeline"
        );

    const video =
        document.getElementById(
            "s22Video"
        );

    if(
        !timeline ||
        !video
    ){
        return;
    }

    const duration =
        Number(
            video.duration ||
            1
        );

    const events =
        s22FilteredEvents();

    timeline.innerHTML = `
        ${
            events
                .map(
                    event => `
                        <div
                            class="
                                s22-event-dot
                                ${
                                    event.team ===
                                    "opp"
                                        ? "opp"
                                        : ""
                                }
                            "
                            data-s22-dot="${
                                s13Esc(
                                    event.id
                                )
                            }"
                            title="${
                                s13Esc(
                                    s22EventLabel(
                                        event.type
                                    )
                                )
                            } · ${
                                s22FormatTime(
                                    event.time
                                )
                            }"
                            style="
                                left:${
                                    Math.max(
                                        0,
                                        Math.min(
                                            100,
                                            event.time /
                                            duration *
                                            100
                                        )
                                    )
                                }%;
                            "
                        ></div>
                    `
                )
                .join(
                    ""
                )
        }

        <div
            id="s22Playhead"
            class="s22-playhead"
            style="
                left:${
                    Math.max(
                        0,
                        Math.min(
                            100,
                            video.currentTime /
                            duration *
                            100
                        )
                    )
                }%;
            "
        ></div>
    `;

    timeline
        .querySelectorAll(
            "[data-s22-dot]"
        )
        .forEach(
            dot => {

                dot.addEventListener(
                    "click",
                    event => {

                        event.stopPropagation();

                        const item =
                            s22Analytics()
                                ?.events
                                .find(
                                    e =>
                                        e.id ===
                                        dot.dataset
                                            .s22Dot
                                );

                        if(item){

                            s22State.selectedEventId =
                                item.id;

                            video.currentTime =
                                item.start ??
                                item.time;

                            video.play();

                            s22RenderEventList();

                        }

                    }
                );

            }
        );

    timeline.addEventListener(
        "click",
        event => {

            if(
                event.target.closest(
                    "[data-s22-dot]"
                )
            ){
                return;
            }

            const rect =
                timeline.getBoundingClientRect();

            const pct =
                Math.max(
                    0,
                    Math.min(
                        1,
                        (
                            event.clientX -
                            rect.left
                        ) /
                        rect.width
                    )
                );

            video.currentTime =
                pct *
                duration;

        }
    );

}


function s22UpdatePlayhead(){

    const video =
        document.getElementById(
            "s22Video"
        );

    const playhead =
        document.getElementById(
            "s22Playhead"
        );

    if(
        !video ||
        !playhead ||
        !video.duration
    ){
        return;
    }

    playhead.style.left =
        (
            video.currentTime /
            video.duration *
            100
        ) +
        "%";

}


