/* =========================================================
   V22 EVENT LIST
========================================================= */

function s22RenderEventList(){

    const list =
        document.getElementById(
            "s22EventList"
        );

    if(!list){
        return;
    }

    const events =
        s22FilteredEvents();

    list.innerHTML =
        events.length
            ? events
                .map(
                    event => `
                        <div
                            class="
                                s22-event-row
                                ${
                                    event.id ===
                                    s22State.selectedEventId
                                        ? "active"
                                        : ""
                                }
                            "
                            data-s22-event="${
                                s13Esc(
                                    event.id
                                )
                            }"
                        >

                            <div class="s22-event-time">
                                ${
                                    s22FormatTime(
                                        event.time
                                    )
                                }
                            </div>

                            <div class="s22-event-type">
                                ${
                                    s13Esc(
                                        s22EventLabel(
                                            event.type
                                        )
                                    )
                                }
                            </div>

                            <div class="s13mut">
                                ${
                                    event.team ===
                                    "own"
                                        ? s13Esc(
                                            s22OwnTeamName()
                                        )
                                        : s13Esc(
                                            s22OpponentName(
                                                s22CurrentProject()
                                            )
                                        )
                                }

                                ${
                                    event.outcome
                                        ? ` · ${s13Esc(event.outcome)}`
                                        : ""
                                }

                                ${
                                    event.zone
                                        ? ` · ${s13Esc(event.zone)}`
                                        : ""
                                }

                                ${
                                    event.note
                                        ? ` · ${s13Esc(event.note)}`
                                        : ""
                                }
                            </div>

                            <div
                                style="
                                    display:flex;
                                    align-items:center;
                                    justify-content:flex-end;
                                    gap:5px;
                                "
                            >
                                <span class="s22-confidence">
                                    ${
                                        Math.round(
                                            Number(
                                                event.confidence ??
                                                1
                                            ) *
                                            100
                                        )
                                    }%
                                </span>

                                <button
                                    type="button"
                                    class="s13btn"
                                    data-event-more="${
                                        s13Esc(
                                            event.id
                                        )
                                    }"
                                >
                                    ⋯
                                </button>
                            </div>

                        </div>
                    `
                )
                .join(
                    ""
                )
            : `
                <div class="s13mut">
                    Ingen events matcher filtrene.
                </div>
            `;

    list
        .querySelectorAll(
            "[data-s22-event]"
        )
        .forEach(
            row => {

                row.addEventListener(
                    "click",
                    event => {

                        if(
                            event.target.closest(
                                "[data-event-more]"
                            )
                        ){
                            return;
                        }

                        const item =
                            s22Analytics()
                                ?.events
                                .find(
                                    e =>
                                        e.id ===
                                        row.dataset
                                            .s22Event
                                );

                        if(!item){
                            return;
                        }

                        s22State.selectedEventId =
                            item.id;

                        const video =
                            document.getElementById(
                                "s22Video"
                            );

                        if(video){

                            video.currentTime =
                                item.start ??
                                item.time;

                            video.play();

                        }

                        s22RenderEventList();

                    }
                );

            }
        );

    list
        .querySelectorAll(
            "[data-event-more]"
        )
        .forEach(
            button => {

                button.addEventListener(
                    "click",
                    event => {

                        event.stopPropagation();

                        const item =
                            s22Analytics()
                                ?.events
                                .find(
                                    e =>
                                        e.id ===
                                        button.dataset
                                            .eventMore
                                );

                        if(!item){
                            return;
                        }

                        const action =
                            window.prompt(
                                "Skriv: clip / delete / note",
                                "clip"
                            );

                        if(
                            action ===
                            "delete"
                        ){

                            s22DeleteEvent(
                                item.id
                            );

                        }else if(
                            action ===
                            "note"
                        ){

                            item.note =
                                window.prompt(
                                    "Note:",
                                    item.note ||
                                    ""
                                ) ??
                                item.note;

                            s13Save();

                            s22RenderEventList();

                        }else if(
                            action ===
                            "clip"
                        ){

                            s22CreateClipFromEvent(
                                item
                            );

                        }

                    }
                );

            }
        );

}


/* =========================================================
   V22 CREATE NORMAL VIDEO CLIP FROM DATA EVENT
========================================================= */

function s22CreateClipFromEvent(event){

    const project =
        s22CurrentProject();

    if(
        !project ||
        !event
    ){
        return;
    }

    project.clips =
        Array.isArray(
            project.clips
        )
            ? project.clips
            : [];

    const existing =
        project.clips.find(
            clip =>
                clip.analyticsEventId ===
                event.id
        );

    if(existing){

        s18State.projectId =
            project.id;

        s18State.clipId =
            existing.id;

        s13Tab =
            "videos";

        s13Render();

        return;

    }

    const clip = {

        id:
            s13Id(
                "analysis-clip"
            ),

        projectId:
            project.id,

        analyticsEventId:
            event.id,

        title:
            `${s22EventLabel(event.type)} · ${s22FormatTime(event.time)}`,

        startSec:
            Number(
                event.start ??
                Math.max(
                    0,
                    event.time -
                    6
                )
            ),

        endSec:
            Number(
                event.end ??
                (
                    event.time +
                    7
                )
            ),

        playerId:
            event.playerId ||
            "",

        attributeId:
            "",

        phase:
            event.type.includes(
                "transition"
            )
                ? (
                    event.type ===
                    "transition_attack"
                        ? "Offensiv omstilling"
                        : "Defensiv omstilling"
                )
                : "Med bold",

        outcome:
            event.team ===
            "own"
                ? "Udvikling"
                : "Korrigering",

        tags:
            [
                event.type,
                event.zone,
                event.source ===
                    "ai"
                    ? "AI"
                    : "MANUEL"
            ]
                .filter(
                    Boolean
                )
                .join(
                    ", "
                ),

        observation:
            event.note ||
            "",

        coachingQuestion:
            "",

        action:
            "",

        showInMeeting:
            false,

        annotations:
            [],

        createdAt:
            new Date().toISOString(),

        updatedAt:
            new Date().toISOString()

    };

    project.clips.push(
        clip
    );

    s13Save();

    visNotification?.(
        "Eventet er oprettet som et normalt videoklip."
    );

}


