/* =========================================================
   V22 AI BACKEND INTEGRATION
========================================================= */

function s22AiEndpoint(){

    return String(
        localStorage.getItem(
            "start11AiAnalysisUrl"
        ) ||
        ""
    )
        .replace(
            /\/+$/,
            ""
        );

}


function s22SetAiEndpoint(){

    const current =
        s22AiEndpoint();

    const next =
        window.prompt(
            "AI backend URL\nFx http://localhost:8000",
            current ||
            "http://localhost:8000"
        );

    if(
        next ===
        null
    ){
        return;
    }

    localStorage.setItem(
        "start11AiAnalysisUrl",
        next.trim()
    );

    visNotification?.(
        "AI endpoint gemt."
    );

    s22UpdateAiBox();

}


async function s22StartAiAnalysis(){

    const endpoint =
        s22AiEndpoint();

    const project =
        s22CurrentProject();

    const a =
        s22Analytics();

    if(
        !endpoint
    ){

        visNotification?.(
            "Sæt først AI backend URL."
        );

        s22SetAiEndpoint();

        return;
    }

    if(
        !project ||
        !project.matchVideo
    ){

        visNotification?.(
            "Projektet mangler en hel kampvideo."
        );

        return;
    }

    const run = {

        id:
            s13Id(
                "ai-run"
            ),

        status:
            "uploading",

        endpoint,

        startedAt:
            new Date().toISOString(),

        jobId:
            "",

        error:
            ""

    };

    a.aiRuns.push(
        run
    );

    a.status =
        "uploading";

    s13Save();

    s22UpdateAiBox();

    try{

        let response;

        if(
            project.matchVideo.sourceType ===
            "local"
        ){

            const stored =
                await s15GetBlob(
                    project.matchVideo.mediaId
                );

            if(
                !stored?.blob
            ){
                throw new Error(
                    "Den lokale videofil kunne ikke læses."
                );
            }

            const form =
                new FormData();

            form.append(
                "file",
                stored.blob,
                project.matchVideo.name ||
                "match.mp4"
            );

            form.append(
                "project_id",
                project.id
            );

            form.append(
                "project_title",
                project.title ||
                ""
            );

            form.append(
                "own_team",
                s22OwnTeamName()
            );

            form.append(
                "opponent",
                s22OpponentName(
                    project
                )
            );

            response =
                await fetch(
                    `${endpoint}/analyze`,
                    {
                        method:
                            "POST",
                        body:
                            form
                    }
                );

        }else{

            response =
                await fetch(
                    `${endpoint}/analyze-url`,
                    {
                        method:
                            "POST",
                        headers:{
                            "Content-Type":
                                "application/json"
                        },
                        body:
                            JSON.stringify({
                                project_id:
                                    project.id,
                                project_title:
                                    project.title ||
                                    "",
                                video_url:
                                    project.matchVideo.url ||
                                    "",
                                own_team:
                                    s22OwnTeamName(),
                                opponent:
                                    s22OpponentName(
                                        project
                                    )
                            })
                    }
                );

        }

        if(
            !response.ok
        ){

            throw new Error(
                `Backend svarede ${response.status}`
            );

        }

        const result =
            await response.json();

        run.jobId =
            result.job_id ||
            result.id ||
            "";

        run.status =
            result.status ||
            "queued";

        a.status =
            run.status;

        s13Save();

        if(
            run.jobId
        ){

            s22PollAiJob(
                run.jobId,
                run.id
            );

        }else if(
            result.events
        ){

            s22ApplyAiResult(
                result,
                run.id
            );

        }else{

            throw new Error(
                "Backend returnerede intet job-id eller analyse."
            );

        }

    }catch(error){

        console.error(
            error
        );

        run.status =
            "error";

        run.error =
            error.message ||
            String(
                error
            );

        a.status =
            "error";

        s13Save();

        s22UpdateAiBox();

        visNotification?.(
            "AI-analysen kunne ikke startes."
        );

    }

}


function s22PollAiJob(jobId,runId){

    clearInterval(
        s22State.aiPollTimer
    );

    const endpoint =
        s22AiEndpoint();

    const a =
        s22Analytics();

    if(
        !endpoint ||
        !a
    ){
        return;
    }

    s22State.aiPollTimer =
        setInterval(
            async () => {

                try{

                    const response =
                        await fetch(
                            `${endpoint}/jobs/${encodeURIComponent(jobId)}`
                        );

                    if(
                        !response.ok
                    ){
                        return;
                    }

                    const result =
                        await response.json();

                    const run =
                        a.aiRuns.find(
                            item =>
                                item.id ===
                                runId
                        );

                    if(run){

                        run.status =
                            result.status ||
                            run.status;

                        run.progress =
                            result.progress ??
                            run.progress;

                    }

                    a.status =
                        result.status ||
                        a.status;

                    s13Save();

                    s22UpdateAiBox();

                    if(
                        result.status ===
                        "completed"
                    ){

                        clearInterval(
                            s22State.aiPollTimer
                        );

                        s22ApplyAiResult(
                            result,
                            runId
                        );

                    }else if(
                        result.status ===
                        "error" ||
                        result.status ===
                        "failed"
                    ){

                        clearInterval(
                            s22State.aiPollTimer
                        );

                        if(run){

                            run.error =
                                result.error ||
                                "Ukendt backend-fejl";

                        }

                        a.status =
                            "error";

                        s13Save();

                        s22UpdateAiBox();

                    }

                }catch(error){

                    console.warn(
                        "AI poll:",
                        error
                    );

                }

            },
            2500
        );

}


function s22ApplyAiResult(result,runId){

    const a =
        s22Analytics();

    if(!a){
        return;
    }

    const incomingEvents =
        Array.isArray(
            result.events
        )
            ? result.events
            : [];

    incomingEvents.forEach(
        raw => {

            const time =
                Number(
                    raw.time ??
                    raw.timestamp ??
                    raw.start ??
                    0
                );

            const event = {

                id:
                    s13Id(
                        "match-event"
                    ),

                type:
                    raw.type ||
                    "note",

                team:
                    raw.team ||
                    "own",

                time,

                start:
                    Number(
                        raw.start ??
                        Math.max(
                            0,
                            time -
                            6
                        )
                    ),

                end:
                    Number(
                        raw.end ??
                        (
                            time +
                            7
                        )
                    ),

                x:
                    raw.x == null
                        ? null
                        : Number(
                            raw.x
                        ),

                y:
                    raw.y == null
                        ? null
                        : Number(
                            raw.y
                        ),

                zone:
                    raw.zone ||
                    (
                        raw.x != null &&
                        raw.y != null
                            ? s22ZoneFromPoint(
                                Number(
                                    raw.x
                                ),
                                Number(
                                    raw.y
                                )
                            )
                            : ""
                    ),

                outcome:
                    raw.outcome ||
                    "",

                note:
                    raw.note ||
                    "",

                playerId:
                    raw.playerId ||
                    raw.player_id ||
                    "",

                playerLabel:
                    raw.player ||
                    raw.player_label ||
                    "",

                source:
                    "ai",

                confidence:
                    Number(
                        raw.confidence ??
                        .5
                    ),

                createdAt:
                    new Date().toISOString()

            };

            a.events.push(
                event
            );

        }
    );

    if(
        Array.isArray(
            result.possession_segments
        )
    ){

        result.possession_segments
            .forEach(
                segment => {

                    a.possessionSegments.push({

                        id:
                            s13Id(
                                "possession"
                            ),

                        team:
                            segment.team ||
                            "own",

                        start:
                            Number(
                                segment.start ||
                                0
                            ),

                        end:
                            Number(
                                segment.end ||
                                0
                            ),

                        source:
                            "ai",

                        confidence:
                            Number(
                                segment.confidence ??
                                .5
                            )

                    });

                }
            );

    }

    a.aiSummary =
        result.summary ||
        a.aiSummary ||
        null;

    a.status =
        "completed";

    const run =
        a.aiRuns.find(
            item =>
                item.id ===
                runId
        );

    if(run){

        run.status =
            "completed";

        run.completedAt =
            new Date().toISOString();

        run.eventCount =
            incomingEvents.length;

    }

    a.updatedAt =
        new Date().toISOString();

    s13Save();

    s22RenderDataHub(
        document.getElementById(
            "s13content"
        )
    );

    visNotification?.(
        `AI-analyse færdig · ${incomingEvents.length} events fundet.`
    );

}


function s22UpdateAiBox(){

    const box =
        document.getElementById(
            "s22AiStatus"
        );

    if(!box){
        return;
    }

    const a =
        s22Analytics();

    const latest =
        [
            ...(
                a?.aiRuns ||
                []
            )
        ]
            .reverse()[0];

    const endpoint =
        s22AiEndpoint();

    box.innerHTML = `
        <div class="s22-ai-box">

            <div
                style="
                    display:flex;
                    justify-content:space-between;
                    gap:8px;
                    align-items:flex-start;
                "
            >

                <div>
                    <div class="s20label">
                        AI MATCH ANALYSIS
                    </div>

                    <div
                        class="s13title"
                        style="margin-top:4px;"
                    >
                        ${
                            latest
                                ? s13Esc(
                                    latest.status ||
                                    "—"
                                )
                                : "Ikke kørt"
                        }
                    </div>

                    <div class="s13mut">
                        ${
                            endpoint
                                ? s13Esc(
                                    endpoint
                                )
                                : "Backend endpoint er ikke sat."
                        }
                    </div>

                    ${
                        latest?.progress != null
                            ? `
                                <div
                                    class="s20-progress"
                                    style="margin-top:8px;"
                                >
                                    <span
                                        style="
                                            width:${
                                                Math.max(
                                                    0,
                                                    Math.min(
                                                        100,
                                                        Number(
                                                            latest.progress
                                                        )
                                                    )
                                                )
                                            }%;
                                        "
                                    ></span>
                                </div>
                            `
                            : ""
                    }

                    ${
                        latest?.error
                            ? `
                                <div
                                    class="s13mut"
                                    style="
                                        margin-top:6px;
                                        color:#ff7b7b;
                                    "
                                >
                                    ${
                                        s13Esc(
                                            latest.error
                                        )
                                    }
                                </div>
                            `
                            : ""
                    }
                </div>

                <div
                    style="
                        display:flex;
                        gap:5px;
                        flex-wrap:wrap;
                        justify-content:flex-end;
                    "
                >
                    <button
                        type="button"
                        id="s22SetEndpoint"
                        class="s13btn"
                    >
                        BACKEND
                    </button>

                    <button
                        type="button"
                        id="s22RunAi"
                        class="s13btn primary"
                    >
                        START AI ANALYSE
                    </button>
                </div>

            </div>

        </div>
    `;

    document.getElementById(
        "s22SetEndpoint"
    )
        ?.addEventListener(
            "click",
            s22SetAiEndpoint
        );

    document.getElementById(
        "s22RunAi"
    )
        ?.addEventListener(
            "click",
            s22StartAiAnalysis
        );

}


